73	   *  offers alongside are the encounter's. Defaults to `subject.type`. */
74	  pickerSubjectType?: SubjectType;
75	}
76	
77	/**
78	 * The v2 fill experience — the questionnaire data-entry page (successor to
79	 * EncounterQuestionnaire + the legacy QuestionnaireForm). Patient-bound
80	 * subjects get two tabs per the reference: the questionnaire canvas (with
81	 * local autosave) and the patient's clinical history; resource subjects
82	 * (location/device/facility) get the canvas alone, since none of the
83	 * clinical context exists for them.
84	 *
85	 * A session may hold SEVERAL questionnaires (the legacy "add another form
86	 * to this submission" capability): each gets its own provider and store,
87	 * the host keeps the registry, and autosave/submit operate on the list.
88	 */
89	export default function QuestionnaireFillPage({
90	  subject,
91	  questionnaireId,
92	  pickerSubjectType = subject.type,
93	}: FillPageProps) {
94	  const { t } = useTranslation();
95	  const [{ continue_draft: continueDraftParam }] = useQueryParams();
96	  const user = useAuthUser();
97	
98	  const patientBound = isPatientBound(subject) ? subject : undefined;
99	  // Server drafts are patient/encounter records — a resource subject can
100	  // only have local drafts, so the query param is ignored there.
101	  const continueDraftId = patientBound ? continueDraftParam : undefined;
102	
103	  useEffect(() => {
104	    sweepExpiredFillDrafts();
105	  }, []);
106	
107	  const fixedQuestionnaire = questionnaireId
108	    ? FIXED_QUESTIONNAIRES[questionnaireId]
109	    : undefined;
110	
111	  const {
112	    data: fetchedQuestionnaire,
113	    isLoading: isQuestionnaireLoading,
114	    isError: isQuestionnaireError,
115	  } = useQuery({
116	    queryKey: questionnaireKeys.detail(questionnaireId ?? ""),
117	    queryFn: query(questionnaireApi.get, {
118	      pathParams: { id: questionnaireId ?? "" },
119	    }),
120	    enabled: !!questionnaireId && !fixedQuestionnaire,
121	  });
122	
123	  const encounterId =
124	    subject.type === "encounter" ? subject.encounterId : undefined;
125	  const { data: encounter, isLoading: isEncounterLoading } = useQuery({
126	    queryKey: ["encounter", encounterId],
127	    queryFn: query(encounterApi.get, {
128	      pathParams: { id: encounterId ?? "" },
129	      queryParams: {
130	        facility: subject.type === "encounter" ? subject.facilityId : "",
131	      },
132	    }),
133	    enabled: !!encounterId,
134	  });
135	
136	  // Patient-subject fills have no encounter to borrow the patient from;
137	  // resource subjects have no patient at all.
138	  const { data: fetchedPatient } = useQuery({
139	    queryKey: ["patient", patientBound?.patientId],
140	    queryFn: query(patientApi.get, {
141	      pathParams: { id: patientBound?.patientId ?? "" },
142	    }),
143	    enabled: subject.type === "patient",
144	  });
145	
146	  const {
147	    data: serverDraft,
148	    isFetching: isServerDraftLoading,
149	    isError: isServerDraftError,
150	  } = useQuery({
151	    queryKey: ["formSubmission", continueDraftId],
152	    queryFn: query(formSubmissionApi.get, {
153	      pathParams: { external_id: continueDraftId ?? "" },
154	    }),
155	    enabled: !!continueDraftId,
156	  });
