379	interface FillPageBodyProps {
380	  questionnaire: QuestionnaireRead;
381	  patient?: PatientRead;
382	  encounter?: EncounterRead;
383	  subject: FillSubject;
384	  pickerSubjectType: SubjectType;
385	  scope: FillDraftScope | undefined;
386	  localDraft: LoadedFillDraft | undefined;
387	  /** Resumed server draft, seeded into the primary form at creation. */
388	  serverDraftResponses?: Record<string, QuestionnaireResponse>;
389	  continueDraftId?: string;
390	  exitTarget: string;
391	}
392	
393	function FillPageBody({
394	  questionnaire,
395	  patient,
396	  encounter,
397	  subject,
398	  pickerSubjectType,
399	  scope,
400	  localDraft,
401	  serverDraftResponses,
402	  continueDraftId,
403	  exitTarget,
404	}: FillPageBodyProps) {
405	  const { t } = useTranslation();
406	  const queryClient = useQueryClient();
407	  const [tab, setTab] = useState<"questionnaire" | "history">("questionnaire");
408	  // History mounts on first activation and stays mounted after (hidden) —
409	  // eager mounting would fire its queries and leak its text into the DOM
410	  // for sessions that never open it, while unmount-on-switch would blank
411	  // adapted structured widgets that keep local state.
412	  const [historyMounted, setHistoryMounted] = useState(false);
413	
414	  // The session: the route-mounted questionnaire plus anything added to
415	  // the same submission. Each entry owns one provider and one store.
416	  const [forms, setForms] = useState<FillFormEntry[]>(() => [
417	    {
418	      key: questionnaire.id,
419	      questionnaire,
420	      isPrimary: true,
421	      initialResponses: serverDraftResponses,
422	    },
423	  ]);
424	  const storesRef = useRef(new Map<string, FormStore>());
425	  const [storesVersion, setStoresVersion] = useState(0);
426	  const handleStore = useCallback((key: string, store: FormStore | null) => {
427	    if (store) storesRef.current.set(key, store);
428	    else storesRef.current.delete(key);
429	    setStoresVersion((version) => version + 1);
430	  }, []);
431	  const getStore = useCallback((key: string) => storesRef.current.get(key), []);
432	
433	  const addQuestionnaire = useCallback(
434	    (
435	      added: QuestionnaireRead,
436	      initialResponses?: Record<string, QuestionnaireResponse>,
437	    ) => {
438	      setForms((previous) =>
439	        previous.some((form) => form.key === added.id)
440	          ? previous
441	          : [
442	              ...previous,
443	              {
444	                key: added.id,
445	                questionnaire: added,
446	                isPrimary: false,
447	                initialResponses,
448	              },
449	            ],
450	      );
451	    },
452	    [],
453	  );
454	  const removeForm = useCallback((key: string) => {
455	    setForms((previous) =>
456	      previous.filter((form) => form.key !== key || form.isPrimary),
457	    );
458	  }, []);
459	
460	  // Snapshots a Resume could not re-fetch. They stay in the persisted
461	  // draft (see `saveFillDraft`'s `retained`) — the two ways a resume can
462	  // fail are NOT the same: a version bump means the answers can no longer
463	  // be trusted onto the new tree and dropping them is correct, while a
464	  // network error means try again later, and destroying the clinician's
465	  // only copy over it is not.
466	  const [retainedSnapshots, setRetainedSnapshots] = useState<
467	    DraftFormSnapshot[]
468	  >([]);
469	
470	  /** Resume for the non-primary snapshots: re-fetch each questionnaire,
471	   *  drop the ones whose version moved on (their answers can no longer be
472	   *  trusted onto the new tree), seed the rest, and keep the ones that
473	   *  could not be fetched at all in the draft. */
474	  const onResumeAddedForms = useCallback(
475	    (snapshots: DraftFormSnapshot[]) => {
476	      void (async () => {
477	        for (const snapshot of snapshots) {
478	          try {
479	            const fetched = await queryClient.fetchQuery({
480	              queryKey: questionnaireKeys.detail(snapshot.questionnaireId),
481	              queryFn: query(questionnaireApi.get, {
482	                pathParams: { id: snapshot.questionnaireId },
483	              }),
484	            });
485	            if (String(fetched.version) !== snapshot.questionnaireVersion) {
486	              toast.warning(
487	                t("fill_draft_form_dropped", { title: fetched.title }),
488	              );
489	              continue;
490	            }
491	            addQuestionnaire(
492	              fetched,
493	              mergeDraftIntoSeed(fetched.questions, snapshot.responses),
494	            );
495	          } catch {
496	            // Transient by assumption: the app's query default is
497	            // retry:false, so one network blip lands here. The snapshot
498	            // keeps its place in the stored draft instead of being erased
499	            // by the next persist. The snapshot's stored title is the only
500	            // human name left when the questionnaire cannot be fetched;
501	            // drafts written before that field existed fall back to the id.
502	            setRetainedSnapshots((previous) =>
503	              previous.some(
504	                (entry) => entry.questionnaireId === snapshot.questionnaireId,
505	              )
506	                ? previous
507	                : [...previous, snapshot],
508	            );
509	            toast.warning(
510	              t("fill_draft_form_unavailable", {
511	                title: snapshot.title ?? snapshot.questionnaireId,
512	              }),
513	            );
514	          }
515	        }
516	      })();
517	    },
518	    [queryClient, addQuestionnaire, t],
519	  );
520	
521	  // The outline lives in one shared aside; each form portals its own
522	  // section into it (it must render inside that form's provider).
523	  const [outlineHost, setOutlineHost] = useState<HTMLElement | null>(null);
524	
525	  // The renderer's flat subject view. Memoized on its PRIMITIVES: the
526	  // union arrives as a fresh object literal from the route element on
527	  // every render, so keying on the object itself would never hit.
528	  const { patientId, encounterId, facilityId, resourceId } =
529	    rendererSubjectOf(subject);
530	  const rendererSubject = useMemo(
531	    () => ({ patientId, encounterId, facilityId, resourceId }),
532	    [patientId, encounterId, facilityId, resourceId],
533	  );
534	
535	  // Local autosave PERSISTENCE stands down while resuming a SERVER draft —
536	  // the server copy is authoritative there and keeps its own lifecycle.
537	  // The scope still goes in: dirty tracking guards navigation either way,
538	  // and a successful submit must clear any sibling local draft filed under
539	  // the same key by an earlier plain session.
540	  const autosave = useFillSessionAutosave({
541	    scope,
542	    persistLocally: !continueDraftId,
543	    forms,
544	    getStore,
545	    storesVersion,
546	    restoredDraft: localDraft,
547	    retainedSnapshots,
548	    onResumeAddedForms,
549	  });
550	
551	  const { submit, isPending, serverErrors } = useSubmitFillSession({
552	    forms,
553	    getStore,
554	    subject,
555	    continueDraftId,
556	    onSuccess: () => {
557	      // Order matters: finishDraft flushes the pristine state before the
558	      // redirect so useNavigationPrompt doesn't block it.
559	      autosave.finishDraft();
560	      navigate(exitTarget);
561	    },
562	  });
563	
564	  // The deliberate server draft (feature-flagged). Same exit as a
565	  // submission: the server copy supersedes the local autosave one, so
566	  // finishDraft drops it and flushes the page pristine before we navigate.
567	  const serverDraftSave = useSaveServerDraft({
568	    forms,
569	    getStore,
570	    subject,
571	    continueDraftId,
572	    onSaved: () => {
573	      autosave.finishDraft();
574	      navigate(exitTarget);
575	    },
576	  });
577	
578	  useNavigationPrompt(
579	    autosave.dirty && !import.meta.env.DEV,
580	    t("unsaved_changes"),
581	  );
582	
583	  // What a federated agent (Scribe) may do to this session, and the one
584	  // validated path for doing it. Nothing is registered for a session with
585	  // no patient in scope, so those mounts hand the plugin an empty list.
586	  const { descriptors, invoke } = useFillActions({ subject, forms, getStore });
587	
588	  return (
589	    <div className="fixed inset-0 z-40 flex flex-col overflow-hidden bg-gray-100">
590	      <Tabs
591	        value={tab}
592	        onValueChange={(value) => {
593	          if (value === "history") setHistoryMounted(true);
594	          setTab(value as typeof tab);
595	        }}
596	        className="flex min-h-0 flex-1 flex-col"
597	      >
598	        <div className="flex shrink-0 items-center justify-between gap-2 px-4 pt-3 md:px-6">
599	          {/* The clinical history tab exists only where there IS a patient
600	              — a location/device/facility fill gets the plain title in the
601	              same slot, draft badge included. */}
602	          {patientId ? (
603	            <TabsList>
604	              <TabsTrigger value="questionnaire">
605	                <QuestionnaireTitleWithDraftBadge dirty={autosave.dirty} />
606	              </TabsTrigger>
607	              <TabsTrigger value="history">
608	                {t("patient_clinical_history")}
609	              </TabsTrigger>
610	            </TabsList>
611	          ) : (
612	            <div className="flex items-center py-1.5 text-sm font-medium text-gray-900">
613	              <QuestionnaireTitleWithDraftBadge dirty={autosave.dirty} />
614	            </div>
615	          )}
616	          <Button
617	            type="button"
618	            variant="outline"
619	            size="icon"
620	            aria-label={t("close")}
621	            onClick={() => navigate(exitTarget)}
622	          >
623	            <X className="size-4" />
624	          </Button>
625	        </div>
626	
627	        {/* The form panel stays mounted across switches (forceMount +
628	            hidden): some adapted structured widgets keep local state they
629	            never rehydrate from the response — an unmount would blank
630	            them. */}
631	        <TabsContent
632	          value="questionnaire"
633	          forceMount
634	          className="mt-3 flex min-h-0 flex-1 flex-col data-[state=inactive]:hidden"
635	        >
636	          <div className="mx-2 flex min-h-0 flex-1 flex-col rounded-t-xl border border-gray-200 bg-white md:mx-4">
637	            <FillHeader
638	              patient={patient}
639	              encounter={encounter}
640	              facilityId={facilityId}
641	              onCancel={() => navigate(exitTarget)}
642	              onSubmit={() => void submit()}
643	              isSubmitting={isPending}
644	              canSubmit
645	              onSaveDraft={
646	                serverDraftSave.canSaveDraft
647	                  ? serverDraftSave.saveDraft
648	                  : undefined
649	              }
650	              isSavingDraft={serverDraftSave.isSavingDraft}
651	            />
652	            <div className="flex min-h-0 flex-1">
653	              <aside
654	                ref={setOutlineHost}
655	                className="hidden w-72 shrink-0 overflow-y-auto border-r border-gray-200 p-3 lg:block"
656	              />
657	              <section
658	                aria-label={t("form_canvas")}
659	                className="min-w-0 flex-1 space-y-6 overflow-y-auto px-4 py-5 md:px-8"
660	              >
661	                {autosave.restoredDraft && (
662	                  <DraftRestoreBar
663	                    draft={autosave.restoredDraft}
664	                    onResume={autosave.resumeRestoredDraft}
665	                    onDiscard={autosave.discardRestoredDraft}
666	                    onDismiss={autosave.dismissRestoreBar}
667	                  />
668	                )}
669	                <ServerErrorsPanel errors={serverErrors} />
670	                {forms.map((form) => (
671	                  <FillFormSection
672	                    key={form.key}
673	                    form={form}
674	                    subject={rendererSubject}
675	                    outlineHost={outlineHost}
676	                    outlineLabel={
677	                      forms.length > 1 ? form.questionnaire.title : undefined
678	                    }
679	                    onStore={handleStore}
680	                    onRemove={forms.length > 1 ? removeForm : undefined}
681	                  />
682	                ))}
683	                {/* A resumed SERVER draft is one questionnaire's
684	                    submission by construction — no adding to it. */}
685	                {!continueDraftId && (
686	                  <div className="mx-auto flex w-full max-w-3xl justify-center">
687	                    <QuestionnaireSearch
688	                      subjectType={pickerSubjectType}
689	                      onSelect={(selected) => addQuestionnaire(selected)}
690	                      // The default trigger is a `role="combobox"` button,
691	                      // and combobox takes no name from its contents — it
692	                      // would reach screen readers unnamed. This one is a
693	                      // plain button, so its label IS its name.
694	                      trigger={
695	                        <Button
696	                          type="button"
697	                          variant="outline"
698	                          className="border-primary-600 text-primary-800"
699	                        >
700	                          <Plus className="size-4" />
701	                          {t("add_questionnaire")}
702	                        </Button>
703	                      }
704	                    />
705	                  </div>
706	                )}
707	                {/* Renders nothing unless a plugin provides Scribe. */}
708	                <PLUGIN_Component
709	                  __name="Scribe"
710	                  actions={descriptors}
711	                  invoke={invoke}
712	                />
713	              </section>
714	            </div>
715	          </div>
716	        </TabsContent>
717	
718	        {patientId && (
719	          <TabsContent
720	            value="history"
721	            forceMount={historyMounted || undefined}
722	            className="mt-3 min-h-0 flex-1 overflow-y-auto px-4 pb-6 data-[state=inactive]:hidden md:px-6"
723	          >
724	            {historyMounted && (
725	              <ClinicalHistoryTab
726	                patientId={patientId}
727	                facilityId={facilityId}
728	              />
729	            )}
730	          </TabsContent>
731	        )}
732	      </Tabs>
733	    </div>
734	  );
735	}
