4	import {
5	  useAnsweredQuestionIds,
6	  useFormRenderer,
7	  useHiddenQuestionIds,
8	} from "@/components/QuestionnaireV2/form/FormContext";
9	import { QuestionTreeNav } from "@/components/QuestionnaireV2/shared/QuestionTreeNav";
10	
11	/**
12	 * The fill page's left outline (≥lg only): the shared tree nav with live
13	 * completion adornments — answered questions get the double-check, open
14	 * ones a dot — and enable_when-hidden rows dropped, exactly like the
15	 * canvas. Selecting a row scrolls its block into view via the renderer's
16	 * `data-question-id` anchors.
17	 *
18	 * `ariaLabel` names the nav landmark: a multi-questionnaire session
19	 * renders one outline per form into the same aside, and repeating the
20	 * generic name would leave a screen reader with several
21	 * indistinguishable "Questions" landmarks — the host passes each form's
22	 * title there instead.
23	 */
24	export function FillOutline({ ariaLabel }: { ariaLabel?: string }) {
25	  const { t } = useTranslation();
26	  const { questionnaire } = useFormRenderer();
27	  const hiddenIds = useHiddenQuestionIds();
28	  const answeredIds = useAnsweredQuestionIds();
29	
30	  return (
31	    <QuestionTreeNav
32	      ariaLabel={ariaLabel ?? t("questions")}
33	      questions={questionnaire.questions}
34	      activeId={null}
35	      hiddenIds={hiddenIds}
36	      onSelect={(questionId) => {
37	        document
38	          .querySelector(`[data-question-id="${questionId}"]`)
39	          ?.scrollIntoView({ behavior: "smooth", block: "start" });
40	      }}
41	      rowAdornment={(question) => {
42	        if (question.type === "group" || question.type === "display") {
43	          return null;
44	        }
45	        return answeredIds.has(question.id) ? (
46	          <CheckCheck className="size-4 text-primary-600" />
47	        ) : (
48	          <Dot className="size-4 text-gray-300" />
49	        );
50	      }}
51	    />
52	  );
53	}
