1	import { Fragment } from "react";
2	import { useTranslation } from "react-i18next";
3	
4	import { cn } from "@/lib/utils";
5	
6	import { Question } from "@/types/questionnaire/question";
7	
8	import { TreeItem, numberQuestions } from "./questionTree";
9	import { QUESTION_TYPE_ICONS } from "./questionTypeIcons";
10	
11	export interface QuestionTreeNavProps {
12	  title?: string;
13	  questions: Question[];
14	  activeId: string | null;
15	  onSelect: (questionId: string) => void;
16	  footer?: React.ReactNode;
17	  /** Builder-only affordances (insert-between "+" buttons etc.) */
18	  renderSeparator?: (afterIndex: number) => React.ReactNode;
19	  /** Question ids (any depth) currently hidden by enable_when (renderer
20	   *  only) — skipped entirely, matching the legacy renderer where hidden
21	   *  questions simply don't appear. Numbering stays stable across hides. */
22	  hiddenIds?: Set<string>;
23	  /** Decorative per-row trailing icons (the studio's logic/issue cues) —
24	   *  rendered aria-hidden so row accessible names stay number + title. */
25	  rowAdornment?: (question: Question) => React.ReactNode;
26	  /** Accessible name for the `nav` landmark when the consumer renders its
27	   *  own visible heading instead of passing `title`. Supply one of the two. */
28	  ariaLabel?: string;
29	}
30	
31	export function QuestionTreeNav({
32	  title,
33	  questions,
34	  activeId,
35	  onSelect,
36	  footer,
37	  renderSeparator,
38	  hiddenIds,
39	  rowAdornment,
40	  ariaLabel,
41	}: QuestionTreeNavProps) {
42	  const { t } = useTranslation();
43	  const items = numberQuestions(questions).filter(
44	    (item) => !hiddenIds?.has(item.question.id),
45	  );
46	
47	  const row = (item: TreeItem, indent: boolean) => {
48	    const { icon: TypeIcon, tint } = QUESTION_TYPE_ICONS[item.question.type];
49	    return (
50	      <button
51	        key={item.question.id}
52	        type="button"
53	        aria-current={activeId === item.question.id ? "true" : undefined}
54	        onClick={() => onSelect(item.question.id)}
55	        className={cn(
56	          "relative flex w-full items-start gap-1 rounded-md px-3 py-2 text-left text-sm",
57	          indent && "ml-2",
58	          activeId === item.question.id
59	            ? "bg-gray-100 font-medium text-gray-900"
60	            : "text-gray-700 hover:bg-gray-50",
61	        )}
62	      >
63	        <span className="shrink-0">{item.number}</span>
64	        {/* Decorative type recognition cue — aria-hidden keeps row names
65	            (number + title) unchanged for a11y and specs. */}
66	        <span
67	          aria-hidden
68	          className={cn(
69	            "mt-px flex size-4 shrink-0 items-center justify-center rounded-sm",
70	            tint,
71	          )}
72	        >
73	          <TypeIcon className="size-3" />
74	        </span>
75	        <span className="min-w-0 flex-1">
76	          {item.question.text || (
77	            <span className="italic text-gray-400">
78	              {t("untitled_question")}
79	            </span>
80	          )}
81	        </span>
82	        {rowAdornment && (
83	          <span
84	            aria-hidden
85	            className="mr-1 flex shrink-0 items-center gap-1 self-center"
86	          >
87	            {rowAdornment(item.question)}
88	          </span>
89	        )}
90	        {activeId === item.question.id && (
91	          <span className="absolute right-0 top-1/2 h-6 w-1 -translate-y-1/2 rounded-full bg-gray-900" />
92	        )}
93	      </button>
94	    );
95	  };
96	
97	  return (
98	    <nav aria-label={ariaLabel ?? title} className="w-full space-y-1">
99	      {title && (
100	        <h3 className="px-3 py-2 text-sm font-semibold text-gray-900">
101	          {title}
102	        </h3>
103	      )}
104	      {items.map((item, index) => {
105	        // Hidden children drop out too — a row for a question that isn't on
106	        // the page is a dead end. Numbering stays stable across hides.
107	        const children = item.children.filter(
108	          (child) => !hiddenIds?.has(child.question.id),
109	        );
110	        return (
111	          <Fragment key={item.question.id}>
112	            {row(item, false)}
113	            {children.length > 0 && (
114	              <div className="ml-3 border-l border-gray-200 pl-1">
115	                {children.map((child) => row(child, true))}
116	              </div>
117	            )}
118	            {index < items.length - 1 && (
119	              <div className="relative my-1 border-t border-gray-100">
120	                {renderSeparator?.(index)}
121	              </div>
122	            )}
123	          </Fragment>
124	        );
125	      })}
126	      {footer}
127	    </nav>
128	  );
129	}
