export const meta = {
  name: 'questionnaire-fill-state-review',
  description: 'Review QuestionnaireV2 fill state management, data flow and submit; adversarially verify findings',
  phases: [
    { title: 'Review', detail: 'four dimension readers over the fill/form engine' },
    { title: 'Verify', detail: 'adversarial refutation of each finding' },
  ],
}

const ROOT = '/Users/bodhishthomas/code/care_fe/src/components/QuestionnaireV2'

const COMMON = `
You are reviewing the QuestionnaireV2 fill experience in the CARE React frontend (repo /Users/bodhishthomas/code/care_fe, branch bodhi/questionnaire-fill). Read ${ROOT}/README.md FIRST — it documents the architecture and several FROZEN contracts (enable_when port behavior, boolean "Yes"/"No" strings, one-renderer rule). Do NOT report frozen contracts as bugs.
There is uncommitted work in the tree (run \`git diff\` to see it): structured render-failure containment (structuredRenderFailedAtom, PluginErrorBoundary onError, validation skips). Review the diff as part of your dimension where relevant.
Report only REAL defects a user or developer would hit: state bugs, race conditions, stale closures, data loss, wrong error routing, memory leaks, broken invalidation. NOT style nits, NOT hypothetical purity concerns, NOT missing features. For each finding give: file (repo-relative), line, title, a failure scenario with concrete steps/state, and severity (critical|major|minor). Max 6 findings; return fewer if the code is clean. An empty list is a valid answer.`

const DIMENSIONS = [
  {
    key: 'engine-store',
    prompt: `${COMMON}
Dimension: the form engine store and validation. Files: ${ROOT}/form/engine/store.ts, ${ROOT}/form/validation.ts, ${ROOT}/form/FormContext.tsx, ${ROOT}/form/engine/types.ts, ${ROOT}/form/FormCanvas.tsx. Focus: atom lifecycle (seeding, live-merge on questionnaire change), enable_when resolution consistency between canvas and validators, the new structuredRenderFailedAtom (identity, when it is READ vs written, does a failed-then-recovered slot ever clear?), useMarkStructuredRenderFailed memo correctness, hidden/answered id derivations.`,
  },
  {
    key: 'submit',
    prompt: `${COMMON}
Dimension: the submit path. Files: ${ROOT}/fill/submit/useSubmitQuestionnaire.ts, ${ROOT}/fill/submit/composeBatch.ts, ${ROOT}/fill/submit/serializeValues.ts, ${ROOT}/fill/submit/validateStructured.ts, ${ROOT}/fill/submit/mapBatchErrors.ts, ${ROOT}/fill/ServerErrorsPanel.tsx. Focus: does client validation and composeBatch agree on which questions submit (disabled subtrees, structured skips, render-failed skips)? Error mapping back to the right form store via reference_id. Multi-form batch composition order. The continueDraftId completion PUT. Scroll-to-first-error behavior. Toast/pending state truthfulness (isPending, double-submit guard).`,
  },
  {
    key: 'drafts',
    prompt: `${COMMON}
Dimension: the draft layers. Files: ${ROOT}/fill/draft/fillDraftStore.ts, ${ROOT}/fill/draft/fillDraftCache.ts, ${ROOT}/fill/draft/useFillAutosave.ts, ${ROOT}/fill/draft/useSaveServerDraft.ts, ${ROOT}/fill/DraftRestoreBar.tsx. Focus: autosave debounce + pagehide/unmount flush correctness, dirty tracking (does it miss edits or stay dirty after submit?), draft scope keying (user/subject/entry questionnaire), version gating on restore, retained snapshots surviving persists, the local-vs-server draft interplay (persistLocally off while resuming server draft), draft cleanup on submit/finishDraft, localStorage quota/corruption handling.`,
  },
  {
    key: 'session-host',
    prompt: `${COMMON}
Dimension: session/host wiring. Files: ${ROOT}/fill/QuestionnaireFillPage.tsx, ${ROOT}/fill/FillFormSection.tsx, ${ROOT}/fill/StoreRegistrar.tsx, ${ROOT}/fill/formSession.ts, ${ROOT}/fill/subject.ts, ${ROOT}/fill/useFillActions.ts, ${ROOT}/form/StructuredSlot.tsx, plus /Users/bodhishthomas/code/care_fe/src/components/Common/PluginErrorBoundary.tsx. Focus: store registry lifecycle (register/unregister races, storesVersion), addQuestionnaire/removeForm edge cases (re-adding a removed form, removing a form with a registered store), onResumeAddedForms async loop (version drift, retained snapshot dedupe), rendererSubject memo, query key hygiene vs ${ROOT}/queryKeys.ts, navigation prompt gating, the serverDraftState memo and its error branches.`,
  },
]

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' },
          line: { type: 'number' },
          title: { type: 'string' },
          scenario: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
        },
        required: ['file', 'title', 'scenario', 'severity'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean' },
    explanation: { type: 'string' },
  },
  required: ['refuted', 'explanation'],
}

const results = await pipeline(
  DIMENSIONS,
  (d) => agent(d.prompt, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA }),
  (review, d) =>
    parallel(
      (review?.findings ?? []).map((f) => () =>
        agent(
          `Adversarially verify this claimed defect in /Users/bodhishthomas/code/care_fe. Read the actual code (and ${ROOT}/README.md for frozen contracts) and try to REFUTE it: show the guard/flow that prevents it, or that it contradicts a documented frozen contract, or that the scenario cannot occur. Default to refuted=true if you cannot reproduce the logic chain concretely. Claim: [${f.severity}] ${f.title} — file ${f.file}${f.line ? ':' + f.line : ''}. Scenario: ${f.scenario}`,
          { label: `verify:${f.title.slice(0, 40)}`, phase: 'Verify', schema: VERDICT_SCHEMA },
        ).then((v) => ({ ...f, dimension: d.key, verdict: v })),
      ),
    ),
)

const all = results.filter(Boolean).flat().filter(Boolean)
const confirmed = all.filter((f) => f.verdict && !f.verdict.refuted)
const refuted = all.filter((f) => f.verdict?.refuted)
log(`${all.length} raw findings, ${confirmed.length} confirmed, ${refuted.length} refuted`)
return { confirmed, refuted: refuted.map((f) => ({ title: f.title, why: f.verdict.explanation })) }

