1	import { EnableWhen, Question } from "@/types/questionnaire/question";
2	
3	/**
4	 * Pure question-tree utilities shared by manage/, builder/ and renderer/.
5	 * Nothing here touches builder state or React — reducer-coupled helpers stay
6	 * in builder/builderReducer.ts, presentation stays in QuestionTreeNav.tsx.
7	 */
8	
9	export interface TreeItem {
10	  question: Question;
11	  number: string;
12	  children: TreeItem[];
13	}
14	
15	/** Top-level questions get 1., 2., …; children get parent.child (1.1., 1.2.). */
16	export function numberQuestions(questions: Question[]): TreeItem[] {
17	  return questions.map((question, i) => ({
18	    question,
19	    number: `${i + 1}.`,
20	    children: (question.questions ?? []).map((child, j) => ({
21	      question: child,
22	      number: `${i + 1}.${j + 1}.`,
23	      children: [],
24	    })),
25	  }));
26	}
27	
28	/** Pre-order depth-first search for the first question matching `predicate`
29	 *  — the one walk shape behind id lookup and the builder's save checks. */
30	export function findFirstQuestion(
31	  questions: Question[],
32	  predicate: (question: Question) => boolean,
33	): Question | undefined {
34	  for (const question of questions) {
35	    if (predicate(question)) return question;
36	    const found = findFirstQuestion(question.questions ?? [], predicate);
37	    if (found) return found;
38	  }
39	  return undefined;
40	}
41	
42	/** Does `question` (or any of its descendants) have id `questionId`? */
43	function containsQuestion(question: Question, questionId: string): boolean {
44	  if (question.id === questionId) return true;
45	  return (question.questions ?? []).some((child) =>
46	    containsQuestion(child, questionId),
47	  );
48	}
49	
50	/** Maps any question id (top-level or nested) to the index of its top-level
51	 *  ancestor in `questions` — so selecting a child in the tree nav pages to
52	 *  its containing top-level question. */
53	export function findTopLevelIndex(
54	  questions: Question[],
55	  questionId: string,
56	): number {
57	  const index = questions.findIndex((question) =>
58	    containsQuestion(question, questionId),
59	  );
60	  return index === -1 ? 0 : index;
61	}
62	
63	/**
64	 * Looks up `questionId`'s own dotted number (e.g. "3." or "3.1.") from
65	 * `numberQuestions`'s two-level output. Returns undefined for ids nested
66	 * deeper than that (grandchildren+), since `numberQuestions` only numbers
67	 * top-level questions and their immediate children — callers should fall
68	 * back to the top-level ancestor's ordinal in that case.
69	 */
70	export function findQuestionNumber(
71	  questions: Question[],
72	  questionId: string,
73	): string | undefined {
74	  for (const item of numberQuestions(questions)) {
75	    if (item.question.id === questionId) return item.number;
76	    const child = item.children.find(
77	      (childItem) => childItem.question.id === questionId,
78	    );
79	    if (child) return child.number;
80	  }
81	  return undefined;
82	}
83	
84	/** Questions that record answers (everything except `group` containers),
85	 *  at any depth — the count surfaces in canvas/outline "N questions" lines. */
86	export function countLeafQuestions(questions: Question[]): number {
87	  let count = 0;
88	  const walk = (list: Question[]) => {
89	    for (const question of list) {
90	      if (question.type === "group") walk(question.questions ?? []);
91	      else count += 1;
92	    }
93	  };
94	  walk(questions);
95	  return count;
96	}
97	
98	/**
99	 * Deep-clones a question tree with fresh `id`s and `link_id`s (used by clone
100	 * and import, where reusing the source's ids would collide with the
101	 * originals once both exist as separate questionnaires/questions).
102	 *
103	 * `enable_when[].question` references point at a sibling's `link_id`, so a
104	 * naive per-question regeneration would leave those references dangling.
105	 * Instead this builds an old→new `link_id` map for the whole tree up front,
106	 * then rewrites every condition's `question` through that map — conditions
107	 * whose target isn't in the map (e.g. it pointed outside the copied subtree)
108	 * are dropped rather than left pointing at a stale id.
109	 *
110	 * Imported/hand-edited trees can carry missing or duplicate `link_id`s. Only
111	 * the FIRST occurrence of an old link_id claims the map entry (so enable_when
112	 * references still resolve deterministically); every other occurrence —
113	 * duplicate or missing — gets its own fresh link_id, instead of collapsing
114	 * all of them onto one shared regenerated id.
115	 *
116	 * `unmappedConditions` picks what happens to a condition whose target is not
117	 * in the map: "drop" (default) for clone/import into a NEW questionnaire,
118	 * where the target will never exist; "keep" for in-questionnaire duplication
119	 * (the studio's Duplicate action), where a condition pointing outside the
120	 * copied subtree still references a live sibling and must survive verbatim.
121	 */
122	export function regenerateQuestionIds(
123	  questions: Question[],
124	  {
125	    unmappedConditions = "drop",
126	  }: { unmappedConditions?: "drop" | "keep" } = {},
127	): Question[] {
128	  const freshLinkId = () => `Q-${crypto.randomUUID().slice(0, 8)}`;
129	
130	  const linkIdMap = new Map<string, string>();
131	  const mapLinkIds = (list: Question[]) => {
132	    for (const question of list) {
133	      if (question.link_id && !linkIdMap.has(question.link_id)) {
134	        linkIdMap.set(question.link_id, freshLinkId());
135	      }
136	      mapLinkIds(Array.isArray(question.questions) ? question.questions : []);
137	    }
138	  };
139	  mapLinkIds(questions);
140	
141	  const remapEnableWhen = (
142	    enableWhen: EnableWhen[] | undefined,
143	  ): EnableWhen[] | undefined =>
144	    unmappedConditions === "keep"
145	      ? enableWhen?.map((condition) =>
146	          linkIdMap.has(condition.question)
147	            ? { ...condition, question: linkIdMap.get(condition.question)! }
148	            : condition,
149	        )
150	      : enableWhen
151	          ?.filter((condition) => linkIdMap.has(condition.question))
152	          .map((condition) => ({
153	            ...condition,
154	            question: linkIdMap.get(condition.question)!,
155	          }));
156	
157	  // Same DFS preorder as mapLinkIds, so the occurrence that claimed the map
158	  // entry is also the first one seen here.
159	  const seen = new Set<string>();
160	  const walk = (list: Question[]): Question[] =>
161	    list.map((question) => {
162	      const mapped =
163	        question.link_id && !seen.has(question.link_id)
164	          ? linkIdMap.get(question.link_id)
165	          : undefined;
166	      if (question.link_id) seen.add(question.link_id);
167	      return {
168	        ...question,
169	        id: crypto.randomUUID(),
170	        link_id: mapped ?? freshLinkId(),
171	        enable_when: remapEnableWhen(question.enable_when),
172	        questions: walk(
173	          Array.isArray(question.questions) ? question.questions : [],
174	        ),
175	      };
176	    });
177	
178	  return walk(questions);
179	}
