48	/**
49	 * `id → signature` for every non-group question — the key that decides
50	 * whether an in-progress answer survives a live tree update. Participates:
51	 * type/structured_type (a differently-shaped value must not linger),
52	 * answer options (value + default flag — a changed `initial_selected` must
53	 * reach the preview, and a recorded answer can't point at a removed
54	 * option), `repeats` (turning it off collapses rendering to `values[0]`
55	 * while enable_when and required validation still scan every entry — extra
56	 * entries would be invisible but live), and the answer value set (swapping
57	 * sets would leave the old set's `coding` recorded).
58	 */
59	function questionSignatures(questions: Question[]): Map<string, string> {
60	  const signatures = new Map<string, string>();
61	  const walk = (list: Question[]) => {
62	    for (const question of list) {
63	      if (question.type === "group") {
64	        walk(question.questions ?? []);
65	        continue;
66	      }
67	      const options = (question.answer_option ?? [])
68	        .map((option) => `${option.value}=${option.initial_selected ? 1 : 0}`)
69	        .join("|");
70	      const valueSet = question.answer_value_set
71	        ? `${question.answer_value_set.slug ?? ""}/${question.answer_value_set.external_id ?? ""}`
72	        : "";
73	      signatures.set(
74	        question.id,
75	        `${question.type}:${question.structured_type ?? ""}:${question.repeats ? 1 : 0}:${valueSet}:${options}`,
76	      );
77	    }
78	  };
79	  walk(questions);
80	  return signatures;
81	}
