83	/**
84	 * Live-update merge — the difference from the old renderer's wholesale
85	 * re-seed (which wiped every in-progress answer whenever the questionnaire
86	 * identity changed). Entries survive when the question id still exists with
87	 * the same type/structured_type; added questions get fresh seeded entries
88	 * (`initial_selected` options); removed questions drop; a type change
89	 * re-seeds that one entry so a stale value of another shape can't linger in
90	 * enable_when evaluation.
91	 */
92	export function syncResponses(
93	  previous: Record<string, QuestionnaireResponse>,
94	  previousSignatures: Map<string, string>,
95	  questions: Question[],
96	): Record<string, QuestionnaireResponse> {
97	  const fresh = initializeResponses(questions);
98	  const nextSignatures = questionSignatures(questions);
99	  const merged: Record<string, QuestionnaireResponse> = {};
100	  for (const [id, seeded] of Object.entries(fresh)) {
101	    const existing = previous[id];
102	    if (!existing || previousSignatures.get(id) !== nextSignatures.get(id)) {
103	      merged[id] = seeded;
104	      continue;
105	    }
106	    // Preserve object identity when nothing about the entry changed, so
107	    // each useQuestionResponse derived atom keeps its Jotai bail-out —
108	    // a title keystroke in the builder must not re-render every block.
109	    merged[id] =
110	      existing.link_id === seeded.link_id
111	        ? existing
112	        : { ...existing, link_id: seeded.link_id };
113	  }
114	  return merged;
115	}
