117	interface ProviderProps {
118	  questionnaire: QuestionnaireRead;
119	  mode: FormMode;
120	  subject?: RendererSubject;
121	  revealHidden?: boolean;
122	  inert?: boolean;
123	  /**
124	   * Creation-time seed overrides (a restored fill draft). Applied once,
125	   * merged over `initializeResponses` so the store is never observed
126	   * unseeded; entries only take effect when the question id still exists
127	   * with the same structured_type (the fill host already gates restores
128	   * on questionnaire id + version, this is defense in depth). Changing
129	   * the prop after mount has no effect by design.
130	   */
131	  initialResponses?: Record<string, QuestionnaireResponse>;
132	  children: React.ReactNode;
133	}
134	
135	export function QuestionnaireFormProvider({
136	  questionnaire,
137	  mode,
138	  subject = {},
139	  revealHidden = false,
140	  inert = false,
141	  initialResponses,
142	  children,
143	}: ProviderProps) {
144	  // useState (not useMemo) so the store is created exactly once per instance
145	  // and never observed unseeded (same rationale as the old provider).
146	  const [store] = useState(() => {
147	    const seeded = createStore();
148	    const responses = initializeResponses(questionnaire.questions);
149	    if (initialResponses) {
150	      for (const [id, entry] of Object.entries(initialResponses)) {
151	        const base = responses[id];
152	        if (base && base.structured_type === entry.structured_type) {
153	          responses[id] = { ...entry, question_id: id, link_id: base.link_id };
154	        }
155	      }
156	    }
157	    seeded.set(questionnaireAtom, questionnaire);
158	    seeded.set(responsesAtom, responses);
159	    return seeded;
160	  });
161	
162	  // Live sync: every questionnaire identity change re-points the atom and
163	  // merges responses instead of wiping them — this is what lets the builder
164	  // feed a fresh draft object per keystroke while preview answers persist.
165	  const previousRef = useRef(questionnaire);
166	  useEffect(() => {
167	    if (previousRef.current === questionnaire) return;
168	    // Metadata-only drafts (Form-settings title/description ride along in
169	    // the studio draft) leave the question tree referentially identical —
170	    // re-point the questionnaire atom, skip the response merge entirely.
171	    if (previousRef.current.questions === questionnaire.questions) {
172	      previousRef.current = questionnaire;
173	      store.set(questionnaireAtom, questionnaire);
174	      return;
175	    }
176	    const previousSignatures = questionSignatures(
177	      previousRef.current.questions,
178	    );
179	    previousRef.current = questionnaire;
180	    store.set(questionnaireAtom, questionnaire);
181	    store.set(
182	      responsesAtom,
183	      syncResponses(
184	        store.get(responsesAtom),
185	        previousSignatures,
186	        questionnaire.questions,
187	      ),
188	    );
189	  }, [questionnaire, store]);
190	
191	  return (
192	    <FormContext.Provider
193	      value={{ mode, subject, questionnaire, revealHidden, inert }}
194	    >
195	      <JotaiProvider store={store}>{children}</JotaiProvider>
196	    </FormContext.Provider>
197	  );
198	}
