114	/** Mirrors QuestionGroup.isQuestionEnabled's `normalizeValue` (old system):
115	 *  booleans normalize to "Yes"/"No", numbers stringify, before ANY operator
116	 *  is applied — matching the old code's unconditional normalization pass. */
117	function normalizeValue(value: unknown): unknown {
118	  if (typeof value === "boolean") return value ? "Yes" : "No";
119	  if (typeof value === "number") return value.toString();
120	  return value;
121	}
