123	/** Direct port of `checkCondition` from the legacy QuestionGroup's
124	 *  isQuestionEnabled (deleted with that stack; see git history for
125	 *  `src/components/Questionnaire/QuestionTypes/QuestionGroup.tsx`),
126	 *  operating on (enableWhen, response) instead of
127	 *  (enableWhen, questionnaireResponses). Preserves faithfully:
128	 *  - the unanswered-dependency short-circuit (no recorded values → false,
129	 *    for every operator, before any comparison runs)
130	 *  - evaluating against ALL of the dependent question's values (not just
131	 *    the first), via `.some()` / `.includes()` over the normalized values
132	 *  - normalizeValue being applied unconditionally before every operator */
133	export function evaluateEnableWhen(
134	  enableWhen: EnableWhen,
135	  response: QuestionnaireResponse | undefined,
136	): boolean {
137	  const dependentValues = response?.values;
138	
139	  if (!dependentValues || dependentValues.length === 0) return false;
140	
141	  const normalizedAnswers = dependentValues.map((v) => normalizeValue(v.value));
142	
143	  switch (enableWhen.operator) {
144	    case "exists":
145	      return (
146	        normalizedAnswers.length > 0 &&
147	        normalizedAnswers.some((v) => v !== "" && v !== null && v !== undefined)
148	      );
149	
150	    case "equals":
151	      // enableWhen.answer is boolean | string here (EnableWhenBoolean |
152	      // EnableWhenString). Legacy questionnaires store JSON true/false while
153	      // responses normalize to "Yes"/"No" — run the stored answer through
154	      // the same normalization so those conditions can ever match. (Only
155	      // literal booleans are normalized; string answers pass through
156	      // untouched, so non-boolean comparisons are unaffected.)
157	      return normalizedAnswers.includes(normalizeValue(enableWhen.answer));
158	
159	    case "not_equals":
160	      // enableWhen.answer is boolean | string here (EnableWhenBoolean | EnableWhenString)
161	      return !normalizedAnswers.includes(normalizeValue(enableWhen.answer));
162	
163	    case "greater":
164	      // enableWhen.answer is number here (EnableWhenNumeric)
165	      return normalizedAnswers.some(
166	        (v) => !isNaN(Number(v)) && Number(v) > enableWhen.answer,
167	      );
168	
169	    case "less":
170	      return normalizedAnswers.some(
171	        (v) => !isNaN(Number(v)) && Number(v) < enableWhen.answer,
172	      );
173	
174	    case "greater_or_equals":
175	      return normalizedAnswers.some(
176	        (v) => !isNaN(Number(v)) && Number(v) >= enableWhen.answer,
177	      );
178	
179	    case "less_or_equals":
180	      return normalizedAnswers.some(
181	        (v) => !isNaN(Number(v)) && Number(v) <= enableWhen.answer,
182	      );
183	
184	    default:
185	      return true;
186	  }
187	}
