38	  /** Creation-time seed overrides (a restored draft) — forwarded verbatim
39	   *  to the provider, which applies them once. See FormContext. */
40	  initialResponses?: Record<string, QuestionnaireResponse>;
41	  /** Decoration seam — see chrome.tsx. */
42	  chrome?: FormChrome;
43	}
44	
45	/**
46	 * The renderer: the whole questionnaire on one scroll — top-level groups
47	 * as section cards, everything live against the per-instance store. The
48	 * studio canvas, the read-only previews and the fill flow all mount this
49	 * one module; there is no second renderer.
50	 */
51	export function QuestionnaireFormRenderer({
52	  questionnaire,
53	  mode,
54	  subject,
55	  revealHidden,
56	  inert,
57	  initialResponses,
58	  chrome = {},
59	  emptyState,
60	  hideHeader,
61	  headerHint,
62	  className,
63	}: QuestionnaireFormRendererProps) {
64	  return (
65	    <QuestionnaireFormProvider
66	      questionnaire={questionnaire}
67	      mode={mode}
68	      subject={subject}
69	      revealHidden={revealHidden}
70	      inert={inert}
71	      initialResponses={initialResponses}
72	    >
73	      <FormChromeProvider chrome={chrome}>
74	        <CanvasBody
75	          emptyState={emptyState}
76	          hideHeader={hideHeader}
77	          headerHint={headerHint}
78	          className={className}
79	        />
80	      </FormChromeProvider>
81	    </QuestionnaireFormProvider>
82	  );
83	}
84	
85	/**
86	 * The canvas body for hosts that mount `QuestionnaireFormProvider`
87	 * themselves — the studio does, so its outline and canvas share one store
88	 * (the outline's preview mode reads live enable_when hidden ids).
89	 */
90	export function QuestionnaireFormCanvas({
91	  chrome = {},
92	  emptyState,
93	  hideHeader,
94	  headerHint,
95	  className,
96	}: CanvasSlots & { chrome?: FormChrome }) {
97	  return (
98	    <FormChromeProvider chrome={chrome}>
99	      <CanvasBody
100	        emptyState={emptyState}
101	        hideHeader={hideHeader}
102	        headerHint={headerHint}
103	        className={className}
104	      />
105	    </FormChromeProvider>
106	  );
107	}
108	
109	function CanvasBody({
110	  emptyState,
111	  hideHeader,
112	  headerHint,
113	  className,
114	}: CanvasSlots) {
115	  const { t } = useTranslation();
116	  const { questionnaire, revealHidden } = useFormRenderer();
117	  const { AppendZone } = useFormChrome();
118	  const hasVisibleQuestions = useHasVisibleTopLevelQuestions();
119	  const questions = questionnaire.questions;
120	
121	  const sectionCount = questions.filter(
122	    (question) => question.type === "group",
123	  ).length;
124	  const countLine = [
125	    sectionCount > 0 && t("n_sections", { count: sectionCount }),
126	    t("n_questions", { count: countLeafQuestions(questions) }),
127	  ]
128	    .filter(Boolean)
129	    .join(" · ");
130	
131	  const header = !hideHeader && (
132	    <div className="flex items-baseline justify-between gap-3 pb-4">
133	      <div className="min-w-0 space-y-1">
134	        <h2 className="text-lg font-semibold tracking-tight text-gray-900">
135	          {questionnaire.title}
136	        </h2>
137	        {questionnaire.description && (
138	          <p className="text-sm text-gray-500">{questionnaire.description}</p>
139	        )}
140	        {questions.length > 0 && (
141	          <p className="text-xs text-gray-400">{countLine}</p>
142	        )}
143	      </div>
144	      {headerHint && (
145	        <div className="shrink-0 text-xs text-gray-400">{headerHint}</div>
146	      )}
147	    </div>
148	  );
149	
150	  if (questions.length === 0) {
151	    return (
152	      <div className={cn("mx-auto w-full max-w-3xl", className)}>
153	        {header}
154	        {emptyState ?? (
155	          <div className="rounded-lg bg-white p-8 text-center text-sm text-gray-500">
156	            {t("no_questions_added_yet")}
157	          </div>
158	        )}
159	      </div>
160	    );
161	  }
162	
163	  // Every top-level question hidden by enable_when: explain the empty form
164	  // instead of a blank canvas. The edit canvas (`revealHidden`) never hits
165	  // this — hidden questions render there with a logic badge.
166	  if (!revealHidden && !hasVisibleQuestions) {
167	    return (
168	      <div className={cn("mx-auto w-full max-w-3xl", className)}>
169	        {header}
170	        <div className="p-8 text-center text-sm text-gray-500">
171	          {t("no_visible_questions")}
172	        </div>
173	      </div>
174	    );
175	  }
176	
177	  return (
178	    <div className={cn("mx-auto w-full max-w-3xl", className)}>
179	      {header}
180	      <div className="space-y-4 pb-4">
181	        {questions.map((question, index) => (
182	          <QuestionBlock
183	            key={question.id}
184	            question={question}
185	            parentId={null}
186	            index={index}
187	            siblingCount={questions.length}
188	            depth={0}
189	            number={`${index + 1}.`}
190	          />
191	        ))}
192	        {AppendZone && <AppendZone parentId={null} />}
193	      </div>
194	    </div>
195	  );
196	}
