import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

/**
 * The fill page's outline navigation chrome (≥lg): a slim always-visible
 * rail of per-question tick marks hugging the canvas' left edge, and the
 * full outline panel that floats OVER the canvas on hover/focus/click —
 * per the reference, the outline no longer reserves a fixed column, so
 * the form gets the whole width.
 *
 * This module owns the overlay shell and the shared nav state (active
 * question + scroll command). The rows and ticks themselves are portaled
 * in per form by `FillFormSection` — they must render inside each form's
 * provider to read that form's store — so this component only provides
 * the host elements.
 */

interface FillOutlineNavValue {
  /** The question whose block currently tops the canvas viewport (any
   *  depth — consumers map it to the row/tick they actually render). */
  activeQuestionId: string | null;
  scrollToQuestion: (questionId: string) => void;
}

const FillOutlineNavContext = createContext<FillOutlineNavValue>({
  activeQuestionId: null,
  scrollToQuestion: () => {},
});

export function useFillOutlineNav(): FillOutlineNavValue {
  return useContext(FillOutlineNavContext);
}

/**
 * Scroll-spy over the canvas' `[data-question-id]` anchors: the active
 * question is the last block whose top sits above the tracking line
 * (96px into the scroll viewport), so it flips exactly when a block
 * scrolls under the reader's eye. Recomputes on scroll/resize and on DOM
 * mutations (enable_when showing/hiding blocks, forms added or removed).
 */
function useActiveQuestionId(container: HTMLElement | null): string | null {
  const [activeId, setActiveId] = useState<string | null>(null);

  useEffect(() => {
    if (!container) return;
    let frame = 0;
    const compute = () => {
      frame = 0;
      const blocks = container.querySelectorAll<HTMLElement>(
        "[data-question-id]",
      );
      if (blocks.length === 0) {
        setActiveId(null);
        return;
      }
      const viewportTop = container.getBoundingClientRect().top;
      // Document order puts a group before its children, so "last block
      // above the line" naturally descends into sub-questions as they
      // pass it.
      let current: HTMLElement | undefined;
      for (const block of blocks) {
        if (block.getBoundingClientRect().top - viewportTop <= 96) {
          current = block;
        }
      }
      setActiveId((current ?? blocks[0]).dataset.questionId ?? null);
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(compute);
    };

    compute();
    container.addEventListener("scroll", schedule, { passive: true });
    const resizeObserver = new ResizeObserver(schedule);
    resizeObserver.observe(container);
    const mutationObserver = new MutationObserver(schedule);
    mutationObserver.observe(container, { childList: true, subtree: true });
    return () => {
      container.removeEventListener("scroll", schedule);
      resizeObserver.disconnect();
      mutationObserver.disconnect();
      if (frame) cancelAnimationFrame(frame);
    };
  }, [container]);

  return activeId;
}

export function FillOutlineNavProvider({
  scrollContainer,
  children,
}: {
  /** The canvas' scrolling element — anchors are queried inside it. */
  scrollContainer: HTMLElement | null;
  children: React.ReactNode;
}) {
  const activeQuestionId = useActiveQuestionId(scrollContainer);

  const scrollToQuestion = useCallback(
    (questionId: string) => {
      const root: ParentNode = scrollContainer ?? document;
      root
        .querySelector(`[data-question-id="${CSS.escape(questionId)}"]`)
        ?.scrollIntoView({
          behavior: window.matchMedia("(prefers-reduced-motion: reduce)")
            .matches
            ? "auto"
            : "smooth",
          block: "start",
        });
    },
    [scrollContainer],
  );

  const value = useMemo(
    () => ({ activeQuestionId, scrollToQuestion }),
    [activeQuestionId, scrollToQuestion],
  );
  return (
    <FillOutlineNavContext.Provider value={value}>
      {children}
    </FillOutlineNavContext.Provider>
  );
}

const PANEL_ID = "fill-outline-panel";

/**
 * The overlay shell. Interaction model: hovering or focusing the rail
 * opens the panel; leaving both (or Escape, or focus moving elsewhere)
 * closes it; the rail is also a plain toggle button for touch and
 * keyboard. The rail stays on top of the open panel — its ticks double
 * as the panel's minimap, exactly as in the reference.
 */
export function FillOutlineOverlay({
  onPanelHost,
  onRailHost,
}: {
  onPanelHost: (element: HTMLElement | null) => void;
  onRailHost: (element: HTMLElement | null) => void;
}) {
  const { t } = useTranslation();
  const [open, setOpen] = useState(false);
  const closeTimer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const rootRef = useRef<HTMLDivElement>(null);
  const toggleRef = useRef<HTMLButtonElement>(null);

  const openPanel = useCallback(() => {
    clearTimeout(closeTimer.current);
    setOpen(true);
  }, []);
  // Grace delay so the pointer can cross from rail to panel (and between
  // panel rows) without the overlay snapping shut.
  const scheduleClose = useCallback(() => {
    clearTimeout(closeTimer.current);
    closeTimer.current = setTimeout(() => setOpen(false), 200);
  }, []);
  useEffect(() => () => clearTimeout(closeTimer.current), []);

  return (
    <div
      ref={rootRef}
      className="absolute inset-y-0 left-0 z-30 hidden lg:block"
      onKeyDown={(event) => {
        if (event.key === "Escape" && open) {
          event.stopPropagation();
          setOpen(false);
          toggleRef.current?.focus();
        }
      }}
      onBlurCapture={(event) => {
        if (!rootRef.current?.contains(event.relatedTarget as Node | null)) {
          setOpen(false);
        }
      }}
    >
      <aside
        id={PANEL_ID}
        aria-label={t("questions_outline")}
        inert={!open || undefined}
        onPointerEnter={(event) => {
          if (event.pointerType === "mouse") openPanel();
        }}
        onPointerLeave={(event) => {
          if (event.pointerType === "mouse") scheduleClose();
        }}
        className={cn(
          "absolute inset-y-0 left-0 w-80 overflow-y-auto border-r border-gray-300 bg-white/90 shadow-lg backdrop-blur-sm",
          "transition-[opacity,transform] duration-200 motion-reduce:transition-none",
          open
            ? "translate-x-0 opacity-100"
            : "pointer-events-none -translate-x-3 opacity-0",
        )}
      >
        <div ref={onPanelHost} className="flex flex-col gap-6 py-6 pl-7 pr-4" />
      </aside>
      <button
        ref={toggleRef}
        type="button"
        aria-expanded={open}
        aria-controls={PANEL_ID}
        aria-label={t("questions_outline")}
        onClick={() => (open ? setOpen(false) : openPanel())}
        onPointerEnter={(event) => {
          if (event.pointerType === "mouse") openPanel();
        }}
        onPointerLeave={(event) => {
          if (event.pointerType === "mouse") scheduleClose();
        }}
        onFocus={openPanel}
        className={cn(
          "absolute inset-y-0 left-0 w-6 rounded-r-lg transition-colors",
          "hover:bg-gray-200/50 focus-visible:bg-gray-200/50 focus-visible:outline-none",
        )}
      >
        {/* Tick marks are decorative — the button itself carries the
            accessible name; each form portals its segment in. */}
        <span
          ref={onRailHost}
          aria-hidden="true"
          className="flex w-full flex-col gap-6 pt-8"
        />
      </button>
    </div>
  );
}

import { CheckCheck, Dot } from "lucide-react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import {
  useAnsweredQuestionIds,
  useFormRenderer,
  useHiddenQuestionIds,
} from "@/components/QuestionnaireV2/form/FormContext";
import type { TreeItem } from "@/components/QuestionnaireV2/shared/questionTree";
import {
  findFirstQuestion,
  findTopLevelIndex,
  numberQuestions,
} from "@/components/QuestionnaireV2/shared/questionTree";

import type { Question } from "@/types/questionnaire/question";

import { useFillOutlineNav } from "./FillOutlineOverlay";

/**
 * One form's rows inside the outline overlay panel, per the reference:
 * numbered rows with live completion adornments — answered questions get
 * the double-check, open ones a dot — the question currently in view in
 * indigo with a right-edge bar (scroll-spy via `useFillOutlineNav`), and
 * enable_when-hidden rows dropped, exactly like the canvas. Selecting a
 * row scrolls its block into view via the renderer's `data-question-id`
 * anchors. Group children indent behind a connector line.
 *
 * `ariaLabel` names the nav landmark: a multi-questionnaire session
 * renders one outline per form into the same panel, and repeating the
 * generic name would leave a screen reader with several
 * indistinguishable "Questions" landmarks — the host passes each form's
 * title there instead.
 */
export function FillOutline({ ariaLabel }: { ariaLabel?: string }) {
  const { t } = useTranslation();
  const { questionnaire } = useFormRenderer();
  const hiddenIds = useHiddenQuestionIds();
  const answeredIds = useAnsweredQuestionIds();
  const { activeQuestionId, scrollToQuestion } = useFillOutlineNav();

  const items = numberQuestions(questionnaire.questions).filter(
    (item) => !hiddenIds.has(item.question.id),
  );

  // The outline shows two levels; the scroll-spy reports any depth. An
  // active id with its own row highlights that row, a deeper descendant
  // highlights its top-level ancestor, another form's id highlights
  // nothing here.
  const hasRow = (questionId: string) =>
    items.some(
      (item) =>
        item.question.id === questionId ||
        item.children.some((child) => child.question.id === questionId),
    );
  const activeRowId =
    activeQuestionId === null
      ? null
      : hasRow(activeQuestionId)
        ? activeQuestionId
        : findFirstQuestion(
              questionnaire.questions,
              (question) => question.id === activeQuestionId,
            )
          ? questionnaire.questions[
              findTopLevelIndex(questionnaire.questions, activeQuestionId)
            ]?.id
          : null;

  const stateIcon = (question: Question) => {
    if (question.type === "group" || question.type === "display") return null;
    return answeredIds.has(question.id) ? (
      <CheckCheck className="size-4 shrink-0 text-primary-600" />
    ) : (
      <Dot className="size-4 shrink-0 text-gray-500" />
    );
  };

  const row = (item: TreeItem, indent: boolean) => {
    const active = activeRowId === item.question.id;
    return (
      <button
        key={item.question.id}
        type="button"
        aria-current={active ? "true" : undefined}
        onClick={() => scrollToQuestion(item.question.id)}
        className={cn(
          "relative flex w-full items-center gap-2 rounded-lg py-1.5 pr-2 text-left text-sm",
          indent ? "min-h-9 px-3" : "min-h-10 pl-2",
          active
            ? "font-semibold text-indigo-600"
            : cn(
                "font-medium hover:bg-gray-100",
                indent ? "text-gray-700" : "text-gray-900",
              ),
        )}
      >
        <span className="min-w-0 flex-1">
          <span className="mr-1">{item.number}</span>
          {item.question.text || (
            <span className="italic text-gray-400">
              {t("untitled_question")}
            </span>
          )}
        </span>
        {/* Decorative completion cue — aria-hidden keeps row accessible
            names (number + title) unchanged. */}
        <span aria-hidden className="flex shrink-0 items-center self-center">
          {stateIcon(item.question)}
        </span>
        {active && (
          <span
            aria-hidden
            className="absolute right-0 top-1/2 h-6 w-1 -translate-y-1/2 rounded-l-full bg-indigo-600"
          />
        )}
      </button>
    );
  };

  return (
    <nav aria-label={ariaLabel ?? t("questions")} className="w-full">
      {items.map((item) => {
        // Hidden children drop out too — a row for a question that isn't
        // on the page is a dead end. Numbering stays stable across hides.
        const children = item.children.filter(
          (child) => !hiddenIds.has(child.question.id),
        );
        return (
          <div key={item.question.id} className="py-1">
            {row(item, false)}
            {children.length > 0 && (
              <div className="ml-4 border-l border-gray-300 pl-2">
                {children.map((child) => row(child, true))}
              </div>
            )}
          </div>
        );
      })}
    </nav>
  );
}

import { useFormRenderer } from "@/components/QuestionnaireV2/form/FormContext";
import { useHiddenQuestionIds } from "@/components/QuestionnaireV2/form/FormContext";
import {
  findFirstQuestion,
  findTopLevelIndex,
} from "@/components/QuestionnaireV2/shared/questionTree";

import { cn } from "@/lib/utils";

import { useFillOutlineNav } from "./FillOutlineOverlay";

/**
 * One form's tick marks on the outline rail — the collapsed minimap per
 * the reference: one hairline per visible top-level question, the one
 * containing the question currently in view drawn longer and indigo.
 * Purely decorative (the rail button carries the accessible name); lives
 * inside this form's provider to read enable_when visibility, portaled
 * into the shared rail by `FillFormSection`.
 */
export function FillOutlineRail() {
  const { questionnaire } = useFormRenderer();
  const hiddenIds = useHiddenQuestionIds();
  const { activeQuestionId } = useFillOutlineNav();

  const activeTopId =
    activeQuestionId !== null &&
    findFirstQuestion(
      questionnaire.questions,
      (question) => question.id === activeQuestionId,
    )
      ? questionnaire.questions[
          findTopLevelIndex(questionnaire.questions, activeQuestionId)
        ]?.id
      : null;

  return (
    <span className="flex w-full flex-col gap-3">
      {questionnaire.questions
        .filter((question) => !hiddenIds.has(question.id))
        .map((question) => (
          <span
            key={question.id}
            className={cn(
              "h-px w-4 bg-gray-400 transition-all duration-200 motion-reduce:transition-none",
              question.id === activeTopId && "w-6 bg-indigo-600",
            )}
          />
        ))}
    </span>
  );
}

