}, []);
// Grace delay so the pointer can cross from rail to panel (and between
// panel rows) without the overlay snapping shut.
const scheduleClose = useCallback(() => {
  clearTimeout(closeTimer.current);
  closeTimer.current = setTimeout(() => setOpen(false), 200);
}, []);
useEffect(() => () => clearTimeout(closeTimer.current), []);

// Hover open/close rides NATIVE pointerenter/pointerleave on the shell:
// one boundary covers the rail and the panel together (crossing between
// them never "leaves"), and native listeners keep working where React's
// synthesized enter/leave pair doesn't (embedded browsers/automation
// that deliver mouse input without the full pointerover/out stream).
// Mouse-only: on touch, the tap's simulated enter would open the panel
// an instant before click toggles it shut again.
useEffect(() => {
  const root = rootRef.current;
  if (!root) return;
  const enter = (event: PointerEvent) => {
    if (event.pointerType === "mouse") openPanel();
  };
  const leave = (event: PointerEvent) => {
    if (event.pointerType === "mouse") scheduleClose();
  };
  root.addEventListener("pointerenter", enter);
  root.addEventListener("pointerleave", leave);
  return () => {
    root.removeEventListener("pointerenter", enter);
    root.removeEventListener("pointerleave", leave);
  };
}, [openPanel, scheduleClose]);

