26	import { serializeResponseValues } from "./serializeValues";
27	
28	/**
29	 * A structured type's `buildRequests` threw or rejected.
30	 *
31	 * `buildRequests` is third-party code for plugin types, and the submit
32	 * callback is fired as `void submit()` — an unguarded rejection travelled
33	 * through `Promise.all` and became an unhandled promise rejection, turning
34	 * Save Changes into a silent no-op that blocked EVERY form in the session
35	 * with no toast, no panel and no batch. The host catches this and pins the
36	 * failure to the question that produced it, exactly as `invokeAction`
37	 * contains a thrown plugin action.
38	 */
39	export class StructuredBuildError extends Error {
40	  readonly questionId: string;
41	
42	  constructor(questionId: string, cause: unknown) {
43	    super(`buildRequests failed for structured question ${questionId}`, {
44	      cause,
45	    });
46	    this.name = "StructuredBuildError";
47	    this.questionId = questionId;
48	  }
49	}
50	
51	/** `definition.buildRequests` behind the containment boundary — a
52	 *  synchronous throw and a rejected promise both become one
53	 *  `StructuredBuildError`. */
54	async function buildStructuredRequests(
55	  definition: ResolvedStructuredType,
56	  data: unknown[],
57	  context: StructuredRequestContext,
58	): Promise<StructuredBatchEntry[]> {
59	  try {
60	    return await definition.buildRequests(data, context);
61	  } catch (error) {
62	    throw new StructuredBuildError(context.questionId, error);
63	  }
64	}
