66	export interface ComposeBatchArgs {
67	  questionnaire: QuestionnaireRead;
68	  responses: Record<string, QuestionnaireResponse>;
69	  subject: FillSubject;
70	  /** Resuming a server draft — appends the completion PUT. */
71	  continueDraftId?: string;
72	}
73	
74	/**
75	 * Assemble the one-batch submission (legacy handleSubmit semantics, from
76	 * the v2 store): structured answers become raw domain-API requests via
77	 * each type's `buildRequests` (core types are patient-bound by
78	 * construction — the legacy gate; plugin types may declare a resource
79	 * subject and run there too), plain answers POST to
80	 * `/questionnaire/{id}/submit/` for patient-bound subjects and
81	 * `/questionnaire/{id}/submit_resource/` for resource subjects
82	 * (location/device/facility, which have no patient to record against),
83	 * and a resumed server draft gets its completion PUT (patient-bound
84	 * only). Only questions currently enabled by enable_when contribute —
85	 * same resolution rendering uses.
86	 *
87	 * Pure with respect to UI state: everything it needs arrives as
88	 * arguments, so it is directly exercisable without mounting anything.
89	 *
90	 * Two deliberate divergences from legacy, both in service of "what you see
91	 * is what submits":
92	 * 1. The walk skips the entire subtree of a disabled group (the renderer
93	 *    never shows those questions), while legacy re-checked only each
94	 *    leaf's own conditions and could submit answers recorded under a
95	 *    since-disabled group.
96	 * 2. `isEnabled` applies to STRUCTURED leaves too. Legacy checked nothing
97	 *    at submit time for structured questions — it iterated the recorded
98	 *    responses directly — so data entered while a structured question was
99	 *    enabled still submitted after its OWN enable_when later turned false.
100	 *    Here it does not: flipping the controlling answer takes the section
101	 *    off the canvas and out of the batch together.
102	 */
103	export async function composeBatch({
104	  questionnaire,
105	  responses,
106	  subject,
107	  continueDraftId,
108	}: ComposeBatchArgs): Promise<StructuredBatchEntry[]> {
109	  // Narrowed once, up front: the structured leg and the draft PUT both
110	  // need the patient ids, and a closure cannot carry the narrowing.
111	  const patientBound = isPatientBound(subject) ? subject : undefined;
112	  const renderCtx = rendererSubjectOf(subject);
113	  const linkIndex = buildLinkIndex(questionnaire.questions);
114	  const isEnabled = (question: Question) =>
115	    isQuestionEnabledInState(question, responses, linkIndex);
116	
117	  const requests: StructuredBatchEntry[] = [];
118	  const structuredWork: Promise<StructuredBatchEntry[]>[] = [];
119	  const answeredLeaves: QuestionnaireResponse[] = [];
120	
121	  const walk = (questions: Question[]) => {
122	    for (const question of questions) {
123	      if (!isEnabled(question)) continue;
124	      if (question.type === "group") {
125	        walk(question.questions ?? []);
126	        continue;
127	      }
128	      const response = responses[question.id];
129	      if (!response) continue;
130	
131	      if (question.type === "structured" && question.structured_type) {
132	        // The recorded entries must belong to this question's type — the
133	        // guard `structuredDataOf` used to carry, kept now that the data
134	        // read is untyped.
135	        if (response.structured_type !== question.structured_type) continue;
136	        const definition = resolveStructuredType(question.structured_type);
137	        // A type this deployment doesn't have (plugin disabled) has no
138	        // endpoint to post to — skip it; validateStructured is what tells
139	        // the clinician, and only when the question was required.
140	        if (!definition) continue;
141	        // A type authored onto a questionnaire whose subject_type it
142	        // doesn't declare (legacy data — the studio picker now prevents
143	        // this going forward) never reaches the domain API.
144	        if (!definition.subjects.includes(questionnaire.subject_type)) {
145	          continue;
146	        }
147	        // Core types are patient-bound by construction (every core
148	        // `subjects` list is patient and/or encounter, and every core
149	        // request hangs off a patient id) — that is the legacy gate. A
150	        // PLUGIN type may declare a resource subject; the studio offers it
151	        // there, the slot renders it and validateStructured runs its
152	        // validate, so dropping its requests here would render, validate
153	        // and then silently discard the clinician's data.
154	        if (!patientBound && definition.source !== "plugin") continue;
155	        const data = structuredDataAny(response);
156	        if (data.length === 0) continue;
157	        structuredWork.push(
158	          buildStructuredRequests(definition, data, {
159	            patientId: patientBound?.patientId,
160	            encounterId: renderCtx.encounterId,
161	            facilityId: renderCtx.facilityId,
