1	import { useMutation } from "@tanstack/react-query";
2	import { useCallback, useState } from "react";
3	import { useTranslation } from "react-i18next";
4	import { toast } from "sonner";
5	
6	import {
7	  errorsAtom,
8	  responsesAtom,
9	  structuredRenderFailedAtom,
10	} from "@/components/QuestionnaireV2/form/engine/store";
11	import { collectRequiredErrors } from "@/components/QuestionnaireV2/form/validation";
12	
13	import type { FillFormEntry } from "@/components/QuestionnaireV2/fill/formSession";
14	import type { FormStore } from "@/components/QuestionnaireV2/fill/StoreRegistrar";
15	import type { FillSubject } from "@/components/QuestionnaireV2/fill/subject";
16	import { rendererSubjectOf } from "@/components/QuestionnaireV2/fill/subject";
17	
18	import batchApi from "@/types/base/batch/batchApi";
19	import type { QuestionValidationError } from "@/types/questionnaire/batch";
20	import type { Question } from "@/types/questionnaire/question";
21	import mutate from "@/Utils/request/mutate";
22	
23	import { StructuredBuildError, composeBatch } from "./composeBatch";
24	import type { ServerValidationError } from "./mapBatchErrors";
25	import { mapBatchErrors } from "./mapBatchErrors";
26	import { collectStructuredErrors } from "./validateStructured";
27	
28	interface UseSubmitFillSessionArgs {
29	  /** Every questionnaire in the session, primary first. */
30	  forms: FillFormEntry[];
31	  getStore: (key: string) => FormStore | undefined;
32	  subject: FillSubject;
33	  continueDraftId?: string;
34	  onSuccess: () => void;
35	}
36	
37	/**
38	 * Reveal the first failing question — every block carries the
39	 * `data-question-id` anchor and every input the `question-input-{id}` one.
40	 * Deferred a tick so the error render exists before we measure (same
41	 * reason legacy used setTimeout).
42	 *
43	 * Focus moves as well as the scroll: a `scrollIntoView` alone leaves a
44	 * keyboard or screen-reader user parked on the Save button with no way to
45	 * find what failed. Where the question has no focusable input of its own
46	 * (structured sections, unsupported types) the block itself takes focus
47	 * through a programmatic-only tabindex, so the error text right below it
48	 * is what gets read.
49	 */
50	function scrollToQuestion(questionId: string) {
51	  setTimeout(() => {
52	    const block = document.querySelector<HTMLElement>(
53	      `[data-question-id="${questionId}"]`,
54	    );
55	    if (!block) return;
56	    block.scrollIntoView({ block: "center", behavior: "smooth" });
57	    const input = document.getElementById(`question-input-${questionId}`);
58	    if (input) {
59	      input.focus({ preventScroll: true });
60	      return;
61	    }
62	    block.setAttribute("tabindex", "-1");
63	    block.focus({ preventScroll: true });
64	  });
65	}
66	
67	/** `questionId → formKey` across the whole session, so a batch failure
68	 *  lands in the store of the form that owns the question. */
69	function buildQuestionOwnerIndex(forms: FillFormEntry[]): Map<string, string> {
70	  const questionToForm = new Map<string, string>();
71	  for (const form of forms) {
72	    const walk = (questions: Question[]) => {
73	      for (const question of questions) {
74	        questionToForm.set(question.id, form.key);
75	        if (question.questions) walk(question.questions);
76	      }
77	    };
78	    walk(form.questionnaire.questions);
79	  }
80	  return questionToForm;
81	}
82	
83	/**
84	 * The fill host's submit action — the errorsAtom writer the engine
85	 * documented since the fill seams landed. Lives outside the form
86	 * providers and reaches each form's instance store through the host's
87	 * registry, so one click submits the whole session.
88	 *
89	 * Flow: client validation (required + structured registry validators)
90	 * runs per form, writes failures into that form's `errorsAtom` and aborts
91	 * with a scroll to the first one; otherwise every form composes its
92	 * requests into ONE batch (legacy semantics — the added questionnaires
93	 * ride along with the primary), and failures map back per reference_id
94	 * into the owning form's `errorsAtom` plus the page-level panel.
95	 */
96	export function useSubmitFillSession({
97	  forms,
98	  getStore,
99	  subject,
100	  continueDraftId,
101	  onSuccess,
102	}: UseSubmitFillSessionArgs) {
103	  const { t } = useTranslation();
104	  const [serverErrors, setServerErrors] = useState<ServerValidationError[]>([]);
105	
106	  const { mutate: submitBatch, isPending } = useMutation({
107	    // Silent: batch failures are handled here (panel + per-question), not
108	    // by the global error toast.
109	    // TODO: migrate to useBatchRequest once it can take pre-built batch
110	    // entries (these requests carry raw urls) and can opt out of the
111	    // global error toast — same blocker the legacy form recorded.
112	    // eslint-disable-next-line @typescript-eslint/no-deprecated
113	    mutationFn: mutate(batchApi.batchRequest, { silent: true }),
114	    onSuccess: () => {
115	      setServerErrors([]);
116	      toast.success(t("questionnaire_submitted_successfully"));
117	      onSuccess();
118	    },
119	    onError: (error) => {
120	      const errorData = error.cause as
121	        | {
122	            results?: Parameters<typeof mapBatchErrors>[0];
123	          }
124	        | undefined;
125	      if (errorData?.results) {
126	        const mapped = mapBatchErrors(
127	          errorData.results,
128	          t("validation_failed"),
129	        );
130	        setServerErrors(mapped.serverErrors);
131	
132	        // Route each question failure to the form that owns it — the
133	        // batch is flat, the stores are not.
134	        const questionToForm = buildQuestionOwnerIndex(forms);
135	        const byForm = new Map<string, QuestionValidationError[]>();
136	        for (const questionError of mapped.questionErrors) {
137	          const formKey = questionToForm.get(questionError.question_id);
138	          if (!formKey) continue;
139	          byForm.set(formKey, [...(byForm.get(formKey) ?? []), questionError]);
140	        }
141	        for (const form of forms) {
142	          getStore(form.key)?.set(errorsAtom, byForm.get(form.key) ?? []);
143	        }
144	        if (mapped.questionErrors.length > 0) {
145	          scrollToQuestion(mapped.questionErrors[0].question_id);
146	        }
147	      }
148	      toast.error(t("questionnaire_submission_failed"));
149	    },
150	  });
151	
152	  const runSubmit = useCallback(async () => {
153	    // 1) Validate every form against its own store; the first failure
154	    //    anywhere in the session decides where we scroll. The renderer's
155	    //    flat subject view and the form's render-failed set go in so the
156	    //    required check can tell a structured question that HAS an input
157	    //    from one showing a notice (see form/validation.ts).
158	    const rendererSubject = rendererSubjectOf(subject);
159	    let firstError: { formKey: string; questionId: string } | undefined;
160	    for (const form of forms) {
161	      const store = getStore(form.key);
162	      if (!store) continue;
163	      const responses = store.get(responsesAtom);
164	      const renderFailed = store.get(structuredRenderFailedAtom);
165	      const clientErrors: QuestionValidationError[] = [
166	        ...collectRequiredErrors(form.questionnaire.questions, responses, t, {
167	          questionnaire: form.questionnaire,
168	          subject: rendererSubject,
169	          renderFailed,
170	        }),
171	        ...collectStructuredErrors(
172	          form.questionnaire,
173	          responses,
174	          rendererSubject,
175	          renderFailed,
176	          t,
177	        ),
178	      ];
179	      store.set(errorsAtom, clientErrors);
180	      if (clientErrors.length > 0 && !firstError) {
181	        firstError = {
182	          formKey: form.key,
183	          questionId: clientErrors[0].question_id,
184	        };
185	      }
186	    }
187	    if (firstError) {
188	      // The per-question messages are `role="alert"` and focus lands on
189	      // the first failure, but the abort itself needs saying out loud too:
190	      // without it a screen-reader user who pressed Save Changes gets no
191	      // signal that the submission was rejected at all.
192	      toast.error(t("validation_failed"));
193	      scrollToQuestion(firstError.questionId);
194	      return;
195	    }
196	    setServerErrors([]);
197	
198	    // 2) One batch across all forms (composeBatch already orders
199	    //    structured requests first WITHIN a form). Only the primary form
200	    //    carries the resumed server draft's completion PUT.
201	    let requests: Awaited<ReturnType<typeof composeBatch>>;
202	    try {
203	      requests = (
204	        await Promise.all(
205	          forms.map((form) => {
206	            const store = getStore(form.key);
207	            if (!store) return Promise.resolve([]);
208	            return composeBatch({
209	              questionnaire: form.questionnaire,
210	              responses: store.get(responsesAtom),
211	              subject,
212	              continueDraftId: form.isPrimary ? continueDraftId : undefined,
213	            });
214	          }),
215	        )
216	      ).flat();
217	    } catch (error) {
218	      // A structured type's `buildRequests` threw. Pin it to the question
219	      // that produced it in that question's own store, and fail the way
220	      // every other submission failure fails — never as a silent no-op.
221	      if (!(error instanceof StructuredBuildError)) throw error;
222	      const formKey = buildQuestionOwnerIndex(forms).get(error.questionId);
223	      for (const form of forms) {
224	        getStore(form.key)?.set(
225	          errorsAtom,
226	          form.key === formKey
227	            ? [
228	                {
229	                  question_id: error.questionId,
230	                  error: t("structured_question_submit_failed"),
231	                },
232	              ]
233	            : [],
234	        );
235	      }
236	      toast.error(t("questionnaire_submission_failed"));
237	      scrollToQuestion(error.questionId);
238	      return;
239	    }
240	    if (requests.length === 0) {
241	      toast.error(t("no_answers_to_submit"));
242	      return;
243	    }
244	    submitBatch({ requests });
245	  }, [forms, getStore, subject, continueDraftId, submitBatch, t]);
246	
247	  /**
248	   * The one entry point, and the outermost containment boundary. The page
249	   * fires this as `onSubmit={() => void submit()}`, so ANY escaping
250	   * rejection — a plugin component's getter, a malformed store record, a
251	   * future call added inside `runSubmit` — would become an unhandled
252	   * promise rejection and turn Save Changes into a silent no-op. Failing
253	   * loudly is the floor: the clinician always learns the submission did
254	   * not happen, and the original error still reaches the console for the
255	   * developer.
256	   */
257	  const submit = useCallback(async () => {
258	    try {
259	      await runSubmit();
260	    } catch (error) {
261	      console.error("Questionnaire submission failed unexpectedly", error);
262	      toast.error(t("questionnaire_submission_failed"));
263	    }
264	  }, [runSubmit, t]);
265	
266	  return { submit, isPending, serverErrors };
267	}
