1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { flushSync } from "react-dom";
3	
4	import {
5	  initializeResponses,
6	  responsesAtom,
7	} from "@/components/QuestionnaireV2/form/engine/store";
8	
9	import type { FillFormEntry } from "@/components/QuestionnaireV2/fill/formSession";
10	import type { FormStore } from "@/components/QuestionnaireV2/fill/StoreRegistrar";
11	
12	import type {
13	  DraftFormSnapshot,
14	  FillDraftScope,
15	  FillSessionFormState,
16	  LoadedFillDraft,
17	} from "./fillDraftStore";
18	import {
19	  clearFillDraft,
20	  mergeDraftIntoSeed,
21	  preserveExcludedStructured,
22	  safeSessionSignature,
23	  saveFillDraft,
24	} from "./fillDraftStore";
25	
26	const AUTOSAVE_DEBOUNCE_MS = 1500;
27	
28	interface UseFillSessionAutosaveArgs {
29	  /** This session's draft key — undefined only before the questionnaire
30	   *  loads. Supplied even in modes that never WRITE a local draft: a
31	   *  successful submit must still clear a sibling draft stored under the
32	   *  same key by an earlier plain session. */
33	  scope: FillDraftScope | undefined;
34	  /** false while resuming a SERVER draft: the server copy is authoritative
35	   *  there, so nothing persists locally. Dirty tracking stays on either
36	   *  way — the unsaved-changes prompt and the Draft chip are about the
37	   *  clinician's un-submitted edits, not about where the bytes live. */
38	  persistLocally?: boolean;
39	  /** Every questionnaire in the session, primary first. */
40	  forms: FillFormEntry[];
41	  getStore: (key: string) => FormStore | undefined;
42	  /** Bumped by the host whenever a StoreRegistrar (un)registers. */
43	  storesVersion: number;
44	  /** The draft this page instance detected, if any. */
45	  restoredDraft: LoadedFillDraft | undefined;
46	  /** Snapshots the host could not turn back into live forms (a resume
47	   *  whose re-fetch failed). They stay in the persisted draft so a
48	   *  transient error cannot destroy their answers. */
49	  retainedSnapshots?: DraftFormSnapshot[];
50	  /** Resume path for forms beyond the primary: the host re-adds them
51	   *  (fetch by id, version-check, seed via initialResponses). */
52	  onResumeAddedForms: (snapshots: DraftFormSnapshot[]) => void;
53	}
54	
55	/**
56	 * The local autosave engine for a whole fill session. Lives OUTSIDE the
57	 * form providers: it reaches each form's instance store through the
58	 * host's registry, subscribes to all of them behind one shared debounce,
59	 * flushes on pagehide/unmount so quick closes keep the last keystrokes,
60	 * and exposes the state the chrome renders (Draft chip, restore bar).
61	 *
62	 * `discardRestoredDraft` clears the stored draft AND resets the forms that
63	 * draft covered back to a pristine seed — the restore bar's one
64	 * destructive affordance, deliberately scoped so it cannot reach a form
65	 * the clinician added after the prompt appeared.
66	 */
67	export function useFillSessionAutosave({
68	  scope,
69	  persistLocally = true,
70	  forms,
71	  getStore,
72	  storesVersion,
73	  restoredDraft,
74	  retainedSnapshots,
75	  onResumeAddedForms,
76	}: UseFillSessionAutosaveArgs) {
77	  const [dirty, setDirty] = useState(false);
78	  const [restoreDismissed, setRestoreDismissed] = useState(false);
79	
80	  // The subscription effect reads these without re-subscribing.
81	  const scopeRef = useRef(scope);
82	  scopeRef.current = scope;
83	  const persistRef = useRef(persistLocally);
84	  persistRef.current = persistLocally;
85	  const retainedRef = useRef(retainedSnapshots);
86	  retainedRef.current = retainedSnapshots;
87	  // Set on successful submit: the draft served its purpose, so neither the
88	  // pending debounce nor the unmount/pagehide flush may re-save it.
89	  const finishedRef = useRef(false);
90	  // Read by resumeRestoredDraft, which only ever fires from an event
91	  // handler well after mount.
92	  const restoredDraftRef = useRef(restoredDraft);
93	  restoredDraftRef.current = restoredDraft;
94	  // A detected draft the clinician has neither resumed nor discarded is
95	  // still theirs to decide about — see persistNow.
96	  const restorePendingRef = useRef(false);
97	  restorePendingRef.current = !!restoredDraft && !restoreDismissed;
98	  /** Fingerprint of the draft-safe state the last settled write saw — the
99	   *  baseline the edit detector compares against. */
100	  const safeSignatureRef = useRef<string | undefined>(undefined);
101	
102	  const scopeKey = scope
103	    ? `${scope.userId}--${scope.subjectKey}--${scope.entryQuestionnaireId}`
104	    : undefined;
105	
106	  /** One snapshot per REGISTERED form — a form whose section hasn't
107	   *  mounted yet simply doesn't contribute. */
108	  const snapshotAll = useCallback((): FillSessionFormState[] => {
109	    const snapshots: FillSessionFormState[] = [];
110	    for (const form of forms) {
111	      const store = getStore(form.key);
112	      if (!store) continue;
113	      snapshots.push({
114	        questionnaire: form.questionnaire,
115	        responses: store.get(responsesAtom),
116	      });
117	    }
118	    return snapshots;
119	  }, [forms, getStore]);
120	
121	  /**
122	   * Write the whole session to its one draft entry. Never runs after a
123	   * successful submit, and never while `persistLocally` is off.
124	   *
125	   * While the restore prompt is still un-acted NOTHING persists: the
126	   * stored draft is the clinician's to accept or discard, and any write
127	   * from this session would either overwrite it (a structured prefetch, a
128	   * keystroke) or — via `saveFillDraft`'s clear-on-empty branch — delete
129	   * it outright.
130	   */
131	  const persistNow = useCallback(() => {
132	    const current = scopeRef.current;
133	    if (!current || !persistRef.current || finishedRef.current) return;
134	    if (restorePendingRef.current) return;
135	    saveFillDraft(current, snapshotAll(), retainedRef.current);
136	  }, [snapshotAll]);
137	
138	  /**
139	   * The session SHAPE changed (a form was added or removed) or a store
140	   * (un)registered — persist now. The debounce cannot cover this: on an
141	   * update React runs the previous effect's cleanup BEFORE the new
142	   * sections' StoreRegistrars register, so that flush would write a
143	   * snapshot missing the just-added forms and silently shrink the stored
144	   * draft (the Resume path re-adds drafted forms exactly this way).
145	   * Gated on `dirty`, because an untouched session is empty and an empty
146	   * save takes `saveFillDraft`'s clear-on-empty branch.
147	   */
148	  useEffect(() => {
149	    if (!scopeKey || !persistLocally || !dirty) return;
150	    persistNow();
151	  }, [
152	    scopeKey,
153	    persistLocally,
154	    dirty,
155	    storesVersion,
156	    retainedSnapshots,
157	    persistNow,
158	  ]);
159	
160	  // Not gated on `scopeKey`/`persistLocally`: dirty tracking is what arms
161	  // the unsaved-changes prompt and the Draft chip, and a session resuming
162	  // a SERVER draft needs both even though it writes no local draft.
163	  // `persistNow` is the thing that stands down, not the subscription.
164	  useEffect(() => {
165	    let timer: ReturnType<typeof setTimeout> | undefined;
166	
167	    const flush = () => {
168	      if (timer === undefined) return;
169	      clearTimeout(timer);
170	      timer = undefined;
171	      persistNow();
172	    };
173	
174	    // Whatever is already in the stores is the baseline, not an edit —
175	    // this is where the structured widgets' prefetched server rows sit.
176	    safeSignatureRef.current = safeSessionSignature(snapshotAll());
177	
178	    // One shared debounce across every form of the session — the draft is
179	    // one localStorage entry, so one timer is all it can honour.
180	    const unsubscribers = forms.flatMap((form) => {
181	      const store = getStore(form.key);
182	      if (!store) return [];
183	      return [
184	        store.sub(responsesAtom, () => {
185	          if (finishedRef.current) return;
186	          // An edit is a change to the DRAFT-SAFE partition. Structured
187	          // types with draftPolicy "exclude" write prefetched server rows
188	          // into the store from mount effects; treating those writes as
189	          // edits marked untouched clinical forms dirty and persisted a
190	          // phantom draft over the clinician's real one.
191	          const signature = safeSessionSignature(snapshotAll());
192	          if (signature === safeSignatureRef.current) return;
193	          safeSignatureRef.current = signature;
194	          setDirty(true);
195	          clearTimeout(timer);
196	          timer = setTimeout(() => {
197	            timer = undefined;
198	            persistNow();
199	          }, AUTOSAVE_DEBOUNCE_MS);
200	        }),
201	      ];
202	    });
203	
204	    // pagehide covers reload/close/bfcache; unmount covers in-app nav.
205	    window.addEventListener("pagehide", flush);
206	    return () => {
207	      window.removeEventListener("pagehide", flush);
208	      flush();
209	      for (const unsubscribe of unsubscribers) unsubscribe();
210	    };
211	    // storesVersion re-runs the subscription when a form (un)registers.
212	  }, [storesVersion, forms, getStore, persistNow, snapshotAll]);
213	
214	  /** Successful submit: drop the stored draft, stop all further saves,
215	   *  and clear the dirty flag SYNCHRONOUSLY (flushSync) — the success
216	   *  handler navigates right after this, and `useNavigationPrompt` must
217	   *  already see a pristine page or it blocks the redirect (the same
218	   *  reason the legacy form flushSync'd `setIsDirty(false)`).
219	   *
220	   *  The clear runs off `scope`, not off whether this session PERSISTED
221	   *  locally: a server-draft session shares its key with the plain mount,
222	   *  and a local draft left behind there would prompt Resume with answers
223	   *  this submit already filed. */
224	  const finishDraft = useCallback(() => {
225	    finishedRef.current = true;
226	    const current = scopeRef.current;
227	    if (current) clearFillDraft(current);
228	    flushSync(() => {
229	      setDirty(false);
230	      setRestoreDismissed(true);
231	    });
232	  }, []);
233	
234	  const discardRestoredDraft = useCallback(() => {
235	    const current = scopeRef.current;
236	    if (current) clearFillDraft(current);
237	    // Only the forms the DISCARDED DRAFT covered go back to a pristine
238	    // seed. "Add questionnaire" is not gated on the prompt, so a
239	    // clinician can add a form and type real answers into it while the
240	    // stale-draft banner is still up — resetting that form too would
241	    // silently destroy work they just did, on a button that promises only
242	    // to drop an old draft.
243	    const covered = new Set(
244	      restoredDraftRef.current?.forms.map(
245	        (snapshot) => snapshot.questionnaireId,
246	      ) ?? [],
247	    );
248	    for (const form of forms) {
249	      if (!covered.has(form.key)) continue;
250	      const store = getStore(form.key);
251	      if (!store) continue;
252	      store.set(
253	        responsesAtom,
254	        preserveExcludedStructured(
255	          store.get(responsesAtom),
256	          initializeResponses(form.questionnaire.questions),
257	        ),
258	      );
259	    }
260	    setDirty(false);
261	    setRestoreDismissed(true);
262	  }, [forms, getStore]);
263	
264	  const dismissRestoreBar = useCallback(() => setRestoreDismissed(true), []);
265	
266	  /** Apply the restored draft — the prompt bar's Resume affordance. The
267	   *  primary form's snapshot lands in the live store through the shared
268	   *  overlay rule; every other snapshot goes back to the host, which
269	   *  re-adds those questionnaires seeded from their snapshots. */
270	  const resumeRestoredDraft = useCallback(() => {
271	    const draft = restoredDraftRef.current;
272	    if (!draft) return;
273	    const primary = forms.find((form) => form.isPrimary);
274	    const addedSnapshots: DraftFormSnapshot[] = [];
275	    for (const snapshot of draft.forms) {
276	      if (primary && snapshot.questionnaireId === primary.key) {
277	        const store = getStore(primary.key);
278	        if (store) {
279	          store.set(
280	            responsesAtom,
281	            preserveExcludedStructured(
282	              store.get(responsesAtom),
283	              mergeDraftIntoSeed(
284	                primary.questionnaire.questions,
285	                snapshot.responses,
286	              ),
287	            ),
288	          );
289	        }
290	        continue;
291	      }
292	      addedSnapshots.push(snapshot);
293	    }
294	    if (addedSnapshots.length > 0) onResumeAddedForms(addedSnapshots);
295	    setDirty(true);
296	    setRestoreDismissed(true);
297	  }, [forms, getStore, onResumeAddedForms]);
298	
299	  return {
300	    /** Any edit since mount — drives the Draft chip. A merely-detected
301	     *  draft is NOT dirty; the chip lights only after Resume or an edit. */
302	    dirty,
303	    restoredDraft: restoreDismissed ? undefined : restoredDraft,
304	    discardRestoredDraft,
305	    dismissRestoreBar,
306	    resumeRestoredDraft,
307	    /** For the submit-success path: the draft served its purpose. */
308	    finishDraft,
309	  };
310	}
