13	/**
14	 * Local fill drafts — the crash/reload safety net. Draft data lives in
15	 * localStorage only under this prefix, scoped per user + subject +
16	 * entry questionnaire, TTL-bounded, and swept on login, logout and app
17	 * update — every eviction hook is deliberate; a new session boundary must
18	 * join the sweep list.
19	 *
20	 * One key holds the WHOLE fill session: the route-mounted questionnaire
21	 * plus every questionnaire added to the same submission.
22	 */
23	const SCHEMA_VERSION = 2;
24	
25	export interface FillDraftScope {
26	  userId: string;
27	  /** encounterId when encounter-bound, else patientId. */
28	  subjectKey: string;
29	  /** The route-mounted questionnaire's id — the session key. */
30	  entryQuestionnaireId: string;
31	}
32	
33	export interface DraftFormSnapshot {
34	  questionnaireId: string;
35	  /** `QuestionnaireRead.version` — a version bump invalidates this form
36	   *  (the read spec exposes no modified_date yet). */
37	  questionnaireVersion: string;
38	  /** The questionnaire's title as it read when the draft was written —
39	   *  the only human name available when a resume can no longer FETCH the
40	   *  questionnaire. Optional because v2 drafts written before this field
41	   *  existed are still valid; every reader must fall back. */
42	  title?: string;
43	  responses: Record<string, QuestionnaireResponse>;
44	  structuredSkipped: boolean;
45	}
46	
47	interface StoredFillDraft {
48	  schemaVersion: number;
49	  savedAt: string;
50	  userId: string;
51	  subjectKey: string;
52	  entryQuestionnaireId: string;
53	  forms: DraftFormSnapshot[];
54	}
55	
56	export interface LoadedFillDraft {
57	  forms: DraftFormSnapshot[];
58	  savedAt: string;
59	  /** True when the saved session had structured answers the draft could
60	   *  not carry (draftPolicy "exclude") — the restore bar says so. */
61	  structuredSkipped: boolean;
62	}
63	
64	function draftKey(scope: FillDraftScope): string {
65	  return `${FILL_DRAFT_PREFIX}${scope.userId}--${scope.subjectKey}--${scope.entryQuestionnaireId}`;
66	}
67	
68	/**
69	 * Split responses into draft-safe entries and skipped structured content.
70	 * Types with `draftPolicy: "exclude"` (every adapted legacy type: their
71	 * values conflate prefetched server rows with user input, and `files`
72	 * holds raw File objects) never enter the draft — restoring stale
73	 * clinical rows and re-upserting them could clobber edits made elsewhere.
74	 */
75	function partitionForDraft(responses: Record<string, QuestionnaireResponse>): {
76	  safe: Record<string, QuestionnaireResponse>;
77	  structuredSkipped: boolean;
78	} {
79	  const safe: Record<string, QuestionnaireResponse> = {};
80	  let structuredSkipped = false;
81	  for (const [id, response] of Object.entries(responses)) {
82	    if (response.structured_type) {
83	      const resolved = resolveStructuredType(response.structured_type);
84	      // An unresolvable type (its plugin isn't loaded) is treated as
85	      // "exclude": nothing here knows whether its values are serializable,
86	      // and a restore would hand them to a component that may never come
87	      // back.
88	      if (!resolved || resolved.draftPolicy === "exclude") {
89	        if (response.values.some(entryHasContent)) structuredSkipped = true;
90	        continue;
91	      }
92	    }
93	    safe[id] = response;
94	  }
95	  return { safe, structuredSkipped };
96	}
97	
98	/** Is this response one the draft deliberately leaves behind? Mirrors
99	 *  `partitionForDraft`'s rule, including its treatment of an unresolvable
100	 *  type as "exclude". */
101	function isDraftExcluded(response: QuestionnaireResponse): boolean {
102	  if (!response.structured_type) return false;
103	  const resolved = resolveStructuredType(response.structured_type);
104	  return !resolved || resolved.draftPolicy === "exclude";
105	}
106	
107	/**
108	 * Overlay the draft-excluded structured entries a store already holds onto
109	 * a record that is about to REPLACE it.
110	 *
111	 * Resume and Discard both swap a form's whole responses record. Structured
112	 * types with `draftPolicy: "exclude"` are by definition not in the draft,
113	 * and the adapted widgets seed them once from a server prefetch in a mount
114	 * effect that never re-runs — so a plain replacement blanks the patient's
115	 * existing allergies/medications/diagnoses on screen, and re-entering them
116	 * upserts DUPLICATE clinical records. The live values are the only copy;
117	 * they carry across untouched.
118	 */
119	export function preserveExcludedStructured(
120	  current: Record<string, QuestionnaireResponse>,
121	  next: Record<string, QuestionnaireResponse>,
122	): Record<string, QuestionnaireResponse> {
123	  const merged = { ...next };
124	  for (const [id, response] of Object.entries(current)) {
125	    if (!isDraftExcluded(response)) continue;
126	    const fresh = merged[id];
127	    // Same guard the draft overlay uses: only where the question still
128	    // exists with the same structured_type.
129	    if (fresh && fresh.structured_type === response.structured_type) {
130	      merged[id] = response;
131	    }
132	  }
133	  return merged;
134	}
135	
136	/** The creation-time merge rule, shared by resume paths: draft entries
137	 *  overlay the fresh seed only when the question still exists with the
138	 *  same structured_type. */
139	export function mergeDraftIntoSeed(
140	  questions: Question[],
141	  draft: Record<string, QuestionnaireResponse>,
142	): Record<string, QuestionnaireResponse> {
143	  const seeded = initializeResponses(questions);
144	  for (const [id, response] of Object.entries(draft)) {
145	    const fresh = seeded[id];
146	    if (fresh && fresh.structured_type === response.structured_type) {
147	      seeded[id] = { ...response, link_id: fresh.link_id };
148	    }
149	  }
150	  return seeded;
151	}
152	
153	/** The live working state of one form, as the fill host reads it out of
154	 *  that form's store. */
155	export interface FillSessionFormState {
156	  questionnaire: QuestionnaireRead;
157	  responses: Record<string, QuestionnaireResponse>;
158	}
159	
160	function snapshotSession(forms: FillSessionFormState[]): {
161	  snapshots: DraftFormSnapshot[];
162	  anyContent: boolean;
163	} {
164	  const snapshots: DraftFormSnapshot[] = [];
165	  let anyContent = false;
166	  for (const form of forms) {
167	    const { safe, structuredSkipped } = partitionForDraft(form.responses);
168	    const hasContent = Object.values(safe).some(
169	      (response) => response.values.some(entryHasContent) || response.note,
170	    );
171	    // `structuredSkipped` ANNOTATES a draft (the restore bar warns about
172	    // it); it never creates one on its own. Adapted structured widgets
173	    // seed prefetched server rows into the store in mount effects, so
174	    // counting the flag as content wrote a phantom draft for a session the
175	    // clinician never touched — and let that phantom overwrite a real
176	    // stored draft on the very next visit.
177	    if (hasContent) anyContent = true;
178	    snapshots.push({
179	      questionnaireId: form.questionnaire.id,
180	      questionnaireVersion: String(form.questionnaire.version),
181	      title: form.questionnaire.title,
182	      responses: safe,
183	      structuredSkipped,
184	    });
185	  }
186	  return { snapshots, anyContent };
187	}
188	
189	/**
190	 * A stable fingerprint of everything a draft WOULD store for this session:
191	 * the draft-safe partition of every form's responses.
192	 *
193	 * Autosave compares it against the last value it saw, so a structured
194	 * widget writing its prefetched server rows (draftPolicy "exclude" — never
195	 * part of a draft) cannot register as a clinician edit. Without this the
196	 * mere act of opening a clinical form lit the Draft chip, armed the
197	 * unsaved-changes prompt and persisted a draft nobody asked for.
198	 */
199	export function safeSessionSignature(forms: FillSessionFormState[]): string {
200	  return JSON.stringify(
201	    forms.map((form) => [
202	      form.questionnaire.id,
203	      partitionForDraft(form.responses).safe,
204	    ]),
205	  );
206	}
207	
208	/** Persist the working state of every form in the session. A session with
209	 *  no draft-SAFE content removes the key instead (never store empty
210	 *  drafts — FiltersCache's clean() convention); draft-excluded structured
211	 *  answers alone are not content, only an annotation on a draft some
212	 *  plain answer already earned. */
213	export function saveFillDraft(
214	  scope: FillDraftScope,
215	  forms: FillSessionFormState[],
216	  /** Snapshots that belong to this draft but are NOT in the live session:
217	   *  a resume whose re-fetch of an added questionnaire failed. They ride
218	   *  through verbatim, because the alternative is that one transient
219	   *  network error during Resume silently and permanently deletes that
220	   *  form's drafted answers. */
221	  retained: DraftFormSnapshot[] = [],
222	): void {
223	  const { snapshots, anyContent } = snapshotSession(forms);
224	  const live = new Set(snapshots.map((snapshot) => snapshot.questionnaireId));
225	  const carried = retained.filter(
226	    (snapshot) => !live.has(snapshot.questionnaireId),
227	  );
228	  const carriedContent = carried.some((snapshot) =>
229	    Object.values(snapshot.responses).some(
230	      (response) => response.values.some(entryHasContent) || response.note,
231	    ),
232	  );
233	  if (!anyContent && !carriedContent) {
234	    clearFillDraft(scope);
235	    return;
236	  }
237	  const draft: StoredFillDraft = {
238	    schemaVersion: SCHEMA_VERSION,
239	    savedAt: new Date().toISOString(),
240	    userId: scope.userId,
241	    subjectKey: scope.subjectKey,
242	    entryQuestionnaireId: scope.entryQuestionnaireId,
243	    forms: [...snapshots, ...carried],
244	  };
245	  try {
246	    localStorage.setItem(draftKey(scope), JSON.stringify(draft));
247	  } catch {
248	    // Quota exceeded / storage disabled — autosave is best-effort.
249	  }
250	}
251	
252	/** JSON round-trips Dates to ISO strings; date/dateTime entries revive to
253	 *  Date objects so the inputs' discriminant checks keep working. Exported
254	 *  for the server-draft (`?continue_draft=`) restore path, whose dump went
255	 *  through the same JSON flattening. */
256	export function reviveDraftResponses(
257	  responses: Record<string, QuestionnaireResponse>,
258	): Record<string, QuestionnaireResponse> {
259	  for (const response of Object.values(responses)) {
260	    // Server dumps are untyped blobs — a `values`-less entry is possible
261	    // and must not throw the whole encounter overview.
262	    for (const entry of response.values ?? []) {
263	      // Fresh from JSON.parse the declared Date is actually a string —
264	      // read through `unknown` at this one boundary.
265	      const raw = (entry as { value?: unknown }).value;
266	      if (
267	        (entry.type === "date" || entry.type === "dateTime") &&
268	        typeof raw === "string"
269	      ) {
270	        const revived = new Date(raw);
271	        entry.value = isNaN(revived.getTime()) ? undefined : revived;
272	      }
273	    }
274	  }
275	  return responses;
276	}
277	
278	/** Load the draft session for this exact scope; anything mismatched,
279	 *  expired or corrupt is removed and reported absent. Only the PRIMARY
280	 *  form's version is checked here — added forms are version-checked when
281	 *  the host re-fetches them on resume. v1 drafts fail the schemaVersion
282	 *  check and are removed; that is the whole migration. */
283	export function loadFillDraft(
284	  scope: FillDraftScope,
285	  primaryVersion: string,
286	): LoadedFillDraft | undefined {
287	  const key = draftKey(scope);
288	  const raw = localStorage.getItem(key);
289	  if (!raw) return undefined;
290	  try {
291	    const draft = JSON.parse(raw) as StoredFillDraft;
292	    const primary = draft.forms?.find(
293	      (form) => form.questionnaireId === scope.entryQuestionnaireId,
294	    );
295	    if (
296	      draft.schemaVersion !== SCHEMA_VERSION ||
297	      draft.userId !== scope.userId ||
298	      draft.subjectKey !== scope.subjectKey ||
299	      draft.entryQuestionnaireId !== scope.entryQuestionnaireId ||
300	      isFillDraftExpired(draft.savedAt) ||
301	      !primary ||
302	      primary.questionnaireVersion !== primaryVersion
303	    ) {
304	      localStorage.removeItem(key);
305	      return undefined;
306	    }
307	    for (const form of draft.forms) {
308	      form.responses = reviveDraftResponses(form.responses);
309	    }
310	    return {
311	      forms: draft.forms,
312	      savedAt: draft.savedAt,
313	      structuredSkipped: draft.forms.some((form) => form.structuredSkipped),
314	    };
315	  } catch {
316	    localStorage.removeItem(key);
317	    return undefined;
318	  }
319	}
320	
321	export function clearFillDraft(scope: FillDraftScope): void {
322	  localStorage.removeItem(draftKey(scope));
323	}
