  DraftFormSnapshot[]
>([]);
const dropRetainedSnapshot = useCallback((questionnaireId: string) => {
  setRetainedSnapshots((previous) =>
    previous.filter((entry) => entry.questionnaireId !== questionnaireId),
  );
