export const meta = {
  name: 'fill-ui-quality-review',
  description: 'Production-quality UI review of the QuestionnaireV2 fill page',
  phases: [
    { title: 'Review', detail: 'four UI dimensions over the fill surface' },
    { title: 'Verify', detail: 'adversarial refutation of each finding' },
  ],
}

const ROOT = '/Users/bodhishthomas/code/care_fe/src/components/QuestionnaireV2'

const COMMON = `
You are reviewing the QuestionnaireV2 FILL page UI in the CARE React frontend (repo /Users/bodhishthomas/code/care_fe, branch bodhi/questionnaire-fill) for production quality. Read ${ROOT}/README.md first for architecture context. The fill surface: ${ROOT}/fill/QuestionnaireFillPage.tsx, FillHeader.tsx, FillOutlineOverlay.tsx, FillOutline.tsx, FillOutlineRail.tsx, FillFormSection.tsx, FillCanvas.tsx, ClinicalHistoryTab.tsx, ServerErrorsPanel.tsx, DraftRestoreBar.tsx, plus ${ROOT}/form/FormCanvas.tsx, QuestionBlock.tsx, SectionCard.tsx and ${ROOT}/form/engine/inputs/.
The outline was JUST redesigned per Figma: a tick rail + hover overlay panel (FillOutlineOverlay) replacing a fixed aside — review the NEW code as it stands.
Report only REAL user-facing defects with a concrete failure scenario. NOT preferences, NOT hypotheticals, NOT restatements of deliberate documented decisions (the files' comments explain many). Max 6 findings; fewer is fine; empty is valid. For each: file (repo-relative), line, title, scenario, severity (critical|major|minor).`

const DIMENSIONS = [
  {
    key: 'a11y',
    prompt: `${COMMON}
Dimension: accessibility. Landmarks and their names (duplicate/unnamed), keyboard operability of the new overlay (toggle, Escape, focus flow, inert usage), aria-expanded/aria-controls/aria-current correctness, focus visibility, screen-reader announcements for async outcomes (toasts vs aria-live), color contrast of the new rail ticks and indigo active states (gray-400 1px hairlines on white, indigo-600 text), touch targets.`,
  },
  {
    key: 'i18n-states',
    prompt: `${COMMON}
Dimension: i18n and UI states. Hardcoded user-facing strings that bypass i18next (check every fill/ file; keys must exist in /Users/bodhishthomas/code/care_fe/public/locale/en.json — spot-check keys used by the fill surface actually exist there), missing loading/empty/error states, skeletons that misrepresent layout, states that dead-end without a way back.`,
  },
  {
    key: 'responsive',
    prompt: `${COMMON}
Dimension: responsive behavior. The overlay is lg-only (hidden below) — what does a md/sm user get (is losing the outline below lg acceptable/it matches the previous behavior — only report REGRESSIONS or breakage)? Header wrapping at narrow widths (FillHeader meta pairs, action band), the canvas' width policy (structured full-width vs 768px column) at tablet sizes, overflow/scroll traps, the tab strip + close button at mobile widths.`,
  },
  {
    key: 'visual-consistency',
    prompt: `${COMMON}
Dimension: visual consistency and polish. Spacing rhythm and alignment across FillHeader/canvas/outline panel, token discipline (gray/primary/indigo usage — the design uses indigo for the active nav state deliberately), hover/focus/active state coverage on interactive elements, transition coherence (motion-reduce respected), z-index layering of the overlay vs dialogs/popovers (overlay z-30 inside a z-40 fixed shell; portals at z-50), dark-mode leakage (app is light-only — ignore), stray borders/radii inconsistencies.`,
  },
]

const FINDINGS_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' },
          line: { type: 'number' },
          title: { type: 'string' },
          scenario: { type: 'string' },
          severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
        },
        required: ['file', 'title', 'scenario', 'severity'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean' },
    explanation: { type: 'string' },
  },
  required: ['refuted', 'explanation'],
}

const results = await pipeline(
  DIMENSIONS,
  (d) => agent(d.prompt, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS_SCHEMA }),
  (review, d) =>
    parallel(
      (review?.findings ?? []).map((f) => () =>
        agent(
          `Adversarially verify this claimed UI defect in /Users/bodhishthomas/code/care_fe. Read the actual code and try to REFUTE it: show the guard that prevents it, or that it is a documented deliberate decision, or that the scenario cannot occur. Default to refuted=true if the chain does not hold concretely. Claim: [${f.severity}] ${f.title} — ${f.file}${f.line ? ':' + f.line : ''}. Scenario: ${f.scenario}`,
          { label: `verify:${f.title.slice(0, 40)}`, phase: 'Verify', schema: VERDICT_SCHEMA },
        ).then((v) => ({ ...f, dimension: d.key, verdict: v })),
      ),
    ),
)

const all = results.filter(Boolean).flat().filter(Boolean)
const confirmed = all.filter((f) => f.verdict && !f.verdict.refuted)
log(`${all.length} raw, ${confirmed.length} confirmed`)
return {
  confirmed: confirmed.map(({ verdict, ...f }) => ({ ...f, why: verdict.explanation.slice(0, 300) })),
  refuted: all.filter((f) => f.verdict?.refuted).map((f) => f.title),
}

